def timesoft_is_configured():
    return bool(str(TIMESOFT_BASE_URL).strip() and str(TIMESOFT_USERNAME).strip() and str(TIMESOFT_PASSWORD).strip())


def _timesoft_safe_request_headers(headers):
    """Chỉ giữ header kỹ thuật an toàn; tuyệt đối không trả Cookie/Authorization ra UI/log."""
    allow = {"accept", "content-type", "x-requested-with", "referer", "origin"}
    safe = {}
    for k, v in (headers or {}).items():
        lk = str(k).lower().strip()
        if lk in allow:
            safe[lk] = str(v)
    return safe


def _timesoft_body_preview(body):
    if body is None:
        return ""
    txt = str(body)
    return txt[:TIMESOFT_PREVIEW_MAX_CHARS]


def _timesoft_json_kind(body_text):
    text0 = str(body_text or "").strip()
    if not text0:
        return ""
    try:
        obj = json.loads(text0)
        if isinstance(obj, dict):
            return "dict:" + ",".join(list(map(str, obj.keys()))[:20])
        if isinstance(obj, list):
            return f"list:{len(obj)}"
    except Exception:
        pass
    return ""


def _timesoft_candidate_score(report_key, item):
    """Chấm điểm request để tự chọn API dữ liệu thật thay vì đoán endpoint."""
    info = TIMESOFT_REPORT_PAGES.get(report_key, {})
    url = str(item.get("url", "")).lower()
    body = str(item.get("body_preview", "")).lower()
    post_data = str(item.get("post_data", "")).lower()
    content_type = str(item.get("content_type", "")).lower()
    score = 0

    if item.get("resource_type") in {"xhr", "fetch"}:
        score += 25
    if int(item.get("status", 0) or 0) == 200:
        score += 8
    if "json" in content_type or item.get("json_kind"):
        score += 18
    if str(item.get("method", "")).upper() == "POST":
        score += 4

    for token in info.get("tokens", []):
        token_l = str(token).lower()
        if token_l and token_l in url:
            score += 24
        if token_l and token_l in body:
            score += 8
        if token_l and token_l in post_data:
            score += 5

    generic_data_tokens = [
        "data", "rows", "items", "result", "total", "amount", "invoice",
        "employee", "checkin", "checkout", "time", "date", "customer",
    ]
    for token in generic_data_tokens:
        if token in body:
            score += 1

    # Giảm điểm các request tài nguyên/telemetry không phải dữ liệu báo cáo.
    if any(x in url for x in ["signalr", "notification", "favicon", "analytics", "chat", "socket"]):
        score -= 20
    return score


def _timesoft_pick_best_candidates(captured_by_report):
    result = {}
    for report_key, items in (captured_by_report or {}).items():
        scored = []
        for item in items:
            clean = dict(item)
            clean["score"] = _timesoft_candidate_score(report_key, clean)
            scored.append(clean)
        scored.sort(key=lambda x: (int(x.get("score", 0)), int(x.get("status", 0) == 200)), reverse=True)
        result[report_key] = {
            "report": TIMESOFT_REPORT_PAGES.get(report_key, {}).get("label", report_key),
            "page_url": urljoin(TIMESOFT_BASE_URL + "/", TIMESOFT_REPORT_PAGES.get(report_key, {}).get("path", "").lstrip("/")),
            "best": scored[0] if scored else None,
            "candidates": scored[:20],
        }
    return result


def _timesoft_visible_input(page, selectors):
    for selector in selectors:
        try:
            loc = page.locator(selector)
            count = min(loc.count(), 12)
            for i in range(count):
                node = loc.nth(i)
                if node.is_visible():
                    return node
        except Exception:
            continue
    return None


def _timesoft_login_error_text(page):
    """Lấy thông báo lỗi đăng nhập đang hiển thị nhưng không lấy giá trị input/credential."""
    selectors = [
        '.validation-summary-errors', '.field-validation-error', '.alert-danger',
        '.alert-warning', '.error', '.error-message', '.text-danger',
        '[role="alert"]', '.toast-message', '.notifyjs-bootstrap-error',
    ]
    messages = []
    for selector in selectors:
        try:
            loc = page.locator(selector)
            for i in range(min(loc.count(), 8)):
                node = loc.nth(i)
                if not node.is_visible():
                    continue
                txt = re.sub(r"\s+", " ", str(node.inner_text() or "")).strip()
                if txt and txt not in messages:
                    messages.append(txt[:300])
        except Exception:
            continue
    return " | ".join(messages[:4])


def _timesoft_login_with_playwright(page, verify_url=None):
    """Đăng nhập TimeSoft và xác minh bằng cách mở lại trang báo cáo thật.

    V80: không kết luận thất bại chỉ vì URL Login chưa đổi ngay sau submit.
    Một số bản TimeSoft xử lý đăng nhập bằng JavaScript/AJAX rồi mới tạo session.
    Sau khi submit, hàm chủ động mở verify_url; chỉ khi verify_url lại redirect về
    /User/Login và vẫn có ô password thì mới xem là đăng nhập thất bại.
    Credential/cookie/authorization tuyệt đối không được ghi ra log/UI.
    """
    password_box = _timesoft_visible_input(page, [
        'input[type="password"]',
        'input[name*="password" i]',
        'input[id*="password" i]',
        'input[name*="pass" i]',
        'input[id*="pass" i]',
    ])
    if password_box is None:
        # Không có ô password: có thể session đã đăng nhập sẵn.
        return True, "Session TimeSoft đã đăng nhập."

    username_box = _timesoft_visible_input(page, [
        'input[name="UserName"]',
        'input[name="Username"]',
        'input[name*="username" i]',
        'input[id*="username" i]',
        'input[name*="user" i]',
        'input[id*="user" i]',
        'input[name*="account" i]',
        'input[id*="account" i]',
        'input[name*="login" i]',
        'input[id*="login" i]',
        'input[type="email"]',
        'input[type="text"]',
    ])
    if username_box is None:
        return False, "Không nhận diện được ô tài khoản trên trang đăng nhập TimeSoft."

    try:
        # click + fill giúp kích hoạt đúng event input/change của framework phía trang web.
        username_box.click()
        username_box.fill(str(TIMESOFT_USERNAME))
        password_box.click()
        password_box.fill(str(TIMESOFT_PASSWORD))
        try:
            password_box.press("Tab")
        except Exception:
            pass
        page.wait_for_timeout(250)
    except Exception as e:
        return False, f"Không nhập được thông tin đăng nhập TimeSoft: {type(e).__name__}"

    submit = None
    submit_selectors = [
        'button[type="submit"]',
        'input[type="submit"]',
        'input[type="button"][value*="đăng" i]',
        'input[type="button"][value*="login" i]',
        'button:has-text("Đăng nhập")',
        'button:has-text("Đăng Nhập")',
        'button:has-text("Login")',
        'a:has-text("Đăng nhập")',
        'a:has-text("Đăng Nhập")',
        '[onclick*="login" i]',
        '[id*="login" i]',
    ]
    for selector in submit_selectors:
        try:
            loc = page.locator(selector)
            for i in range(min(loc.count(), 10)):
                node = loc.nth(i)
                if node.is_visible() and node.is_enabled():
                    submit = node
                    break
            if submit is not None:
                break
        except Exception:
            continue

    try:
        if submit is not None:
            submit.click(timeout=8_000)
        else:
            # Fallback an toàn: Enter trên ô password thường kích hoạt submit/JS login.
            password_box.press("Enter")

        # Không phụ thuộc hoàn toàn vào networkidle vì TimeSoft có thể polling.
        try:
            page.wait_for_load_state("domcontentloaded", timeout=10_000)
        except Exception:
            pass
        page.wait_for_timeout(2_000)
    except Exception as e:
        return False, f"Không gửi được biểu mẫu đăng nhập TimeSoft: {type(e).__name__}"

    # Xác minh session bằng chính trang report, tránh false-negative nếu Login dùng AJAX.
    target_url = verify_url or urljoin(
        TIMESOFT_BASE_URL + "/",
        TIMESOFT_REPORT_PAGES["summary_invoice"]["path"].lstrip("/"),
    )
    try:
        page.goto(target_url, wait_until="domcontentloaded", timeout=35_000)
        try:
            page.wait_for_load_state("networkidle", timeout=8_000)
        except Exception:
            pass
        page.wait_for_timeout(1_000)
    except Exception as e:
        return False, f"Đã gửi đăng nhập nhưng không mở được trang kiểm tra TimeSoft: {type(e).__name__}"

    final_url = str(page.url or "")
    try:
        still_password = _timesoft_visible_input(page, [
            'input[type="password"]',
            'input[name*="password" i]',
            'input[id*="password" i]',
        ])
    except Exception:
        still_password = None

    is_login_url = "/user/login" in final_url.lower()
    if is_login_url and still_password is not None:
        err = _timesoft_login_error_text(page)
        suffix = f" Thông báo từ TimeSoft: {err}" if err else ""
        return False, (
            "TimeSoft vẫn chuyển về trang đăng nhập sau khi xác minh session. "
            "Tài khoản đã được nạp từ Secrets nhưng form/luồng đăng nhập tự động chưa hoàn tất."
            + suffix
        )

    return True, f"Đăng nhập TimeSoft thành công · đã xác minh bằng trang báo cáo ({final_url})."


def timesoft_auto_discover_apis():
    """Tự đăng nhập và bắt XHR/fetch thật của 2 trang báo cáo để xác định API chính xác.

    Không đoán endpoint. Hàm chỉ chọn từ request thực tế do chính trang TimeSoft phát sinh.
    Yêu cầu môi trường có package playwright và Chromium.
    """
    if not timesoft_is_configured():
        return False, "Chưa khai báo đầy đủ [TIMESOFT] trong Streamlit Secrets.", {}

    try:
        from playwright.sync_api import sync_playwright
    except Exception:
        return False, (
            "Chưa có Playwright. Thêm `playwright` vào requirements.txt và cài Chromium "
            "(`playwright install chromium`) để bật Auto Discovery."
        ), {}

    captured = {key: [] for key in TIMESOFT_REPORT_PAGES}
    active_report = {"key": None}
    browser = None

    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu"],
            )
            context = browser.new_context(
                ignore_https_errors=False,
                viewport={"width": 1440, "height": 1000},
                locale="vi-VN",
            )
            page = context.new_page()

            def on_response(response):
                report_key = active_report.get("key")
                if report_key not in captured:
                    return
                try:
                    req = response.request
                    resource_type = str(req.resource_type or "").lower()
                    if resource_type not in {"xhr", "fetch"}:
                        return
                    headers = _timesoft_safe_request_headers(req.headers)
                    content_type = str(response.headers.get("content-type", "") or "")
                    body_text = ""
                    if any(x in content_type.lower() for x in ["json", "text", "javascript", "html"]):
                        try:
                            body_text = response.text() or ""
                        except Exception:
                            body_text = ""
                    if len(body_text) > TIMESOFT_CAPTURE_MAX_CHARS:
                        body_text = body_text[:TIMESOFT_CAPTURE_MAX_CHARS]
                    post_data = req.post_data or ""
                    # Không capture request login vì active_report=None ở bước đăng nhập.
                    captured[report_key].append({
                        "method": str(req.method or "GET").upper(),
                        "url": str(req.url or ""),
                        "resource_type": resource_type,
                        "status": int(response.status or 0),
                        "content_type": content_type,
                        "post_data": str(post_data)[:50_000],
                        "request_headers": headers,
                        "json_kind": _timesoft_json_kind(body_text),
                        "body_preview": _timesoft_body_preview(body_text),
                    })
                except Exception:
                    return

            page.on("response", on_response)

            # Mở trang report trước: TimeSoft sẽ tự redirect đến Login nếu session chưa có.
            first_url = urljoin(
                TIMESOFT_BASE_URL + "/",
                TIMESOFT_REPORT_PAGES["summary_invoice"]["path"].lstrip("/"),
            )
            page.goto(first_url, wait_until="domcontentloaded", timeout=35_000)
            page.wait_for_timeout(1_000)
            ok_login, login_msg = _timesoft_login_with_playwright(page, verify_url=first_url)
            if not ok_login:
                context.close()
                browser.close()
                return False, login_msg, {}

            # Duyệt từng report. Request XHR/fetch được bắt trong on_response ở trên.
            for report_key, info in TIMESOFT_REPORT_PAGES.items():
                active_report["key"] = report_key
                report_url = urljoin(TIMESOFT_BASE_URL + "/", info["path"].lstrip("/"))
                page.goto(report_url, wait_until="domcontentloaded", timeout=35_000)
                # Chờ AJAX của report. networkidle có thể timeout nếu trang dùng polling, nên có fallback.
                try:
                    page.wait_for_load_state("networkidle", timeout=12_000)
                except Exception:
                    pass
                page.wait_for_timeout(4_000)

            active_report["key"] = None
            context.close()
            browser.close()
            browser = None

        picked = _timesoft_pick_best_candidates(captured)
        missing = [k for k, v in picked.items() if not v.get("best")]
        if missing:
            names = ", ".join(TIMESOFT_REPORT_PAGES[k]["label"] for k in missing)
            return False, f"Đã đăng nhập nhưng chưa bắt được XHR/fetch dữ liệu của: {names}.", picked
        return True, "Đã tự đăng nhập và xác định request API thực tế của cả 2 báo cáo TimeSoft.", picked

    except Exception as e:
        try:
            if browser is not None:
                browser.close()
        except Exception:
            pass
        return False, f"TimeSoft Auto Discovery lỗi: {type(e).__name__}: {e}", _timesoft_pick_best_candidates(captured)


def _timesoft_discovery_rows(discovery):
    rows = []
    for report_key, report_info in (discovery or {}).items():
        best = (report_info or {}).get("best") or {}
        rows.append({
            "Báo cáo": (report_info or {}).get("report", report_key),
            "Method": best.get("method", ""),
            "API URL": best.get("url", ""),
            "HTTP": best.get("status", ""),
            "Kiểu": best.get("json_kind", "") or best.get("content_type", ""),
            "Điểm nhận diện": best.get("score", ""),
        })
    return pd.DataFrame(rows)


def _timesoft_sanitized_discovery(discovery):
    """JSON kỹ thuật an toàn hơn: chỉ giữ request cần thiết, không xuất response/PII/token."""
    safe = {}
    allowed = {
        "method", "url", "resource_type", "status", "content_type",
        "post_data", "request_headers", "json_kind", "score",
    }
    for report_key, info in (discovery or {}).items():
        best = (info or {}).get("best") or {}
        safe_best = {k: v for k, v in best.items() if k in allowed}
        # Tuyệt đối không xuất Cookie/Authorization nếu về sau header capture thay đổi.
        headers = dict(safe_best.get("request_headers") or {})
        for bad in ["cookie", "authorization", "proxy-authorization"]:
            headers.pop(bad, None)
        safe_best["request_headers"] = headers
        safe[report_key] = {
            "report": (info or {}).get("report", report_key),
            "page_url": (info or {}).get("page_url", ""),
            "best": safe_best or None,
        }
    return safe


def _timesoft_date_range_text(start_date, end_date):
    if isinstance(start_date, datetime):
        start_date = start_date.date()
    if isinstance(end_date, datetime):
        end_date = end_date.date()
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        raise ValueError("Khoảng ngày TimeSoft không hợp lệ.")
    if start_date > end_date:
        start_date, end_date = end_date, start_date
    return f"{start_date.strftime('%d/%m/%Y')} - {end_date.strftime('%d/%m/%Y')}"


def _timesoft_requests_session_from_browser_cookies(cookies, user_agent=""):
    session = requests.Session()
    session.headers.update({
        "Accept-Language": "vi-VN,vi;q=0.9,en;q=0.7",
        "User-Agent": str(user_agent or "Mozilla/5.0"),
    })
    for cookie in cookies or []:
        name = str(cookie.get("name", "") or "")
        value = str(cookie.get("value", "") or "")
        if not name:
            continue
        kwargs = {}
        domain = str(cookie.get("domain", "") or "").strip()
        path = str(cookie.get("path", "") or "/").strip() or "/"
        if domain:
            kwargs["domain"] = domain
        if path:
            kwargs["path"] = path
        try:
            session.cookies.set(name, value, **kwargs)
        except Exception:
            session.cookies.set(name, value)
    return session


def _timesoft_new_authenticated_http_session():
    """Dùng Playwright chỉ để đăng nhập, sau đó chuyển cookie sang requests.Session."""
    if not timesoft_is_configured():
        return False, "Chưa khai báo đầy đủ [TIMESOFT] trong Streamlit Secrets.", None
    try:
        from playwright.sync_api import sync_playwright
    except Exception:
        return False, "Chưa cài Playwright/Chromium cho TimeSoft.", None

    browser = None
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu"],
            )
            context = browser.new_context(
                ignore_https_errors=False,
                viewport={"width": 1440, "height": 1000},
                locale="vi-VN",
            )
            page = context.new_page()
            verify_url = urljoin(
                TIMESOFT_BASE_URL + "/",
                TIMESOFT_REPORT_PAGES["summary_invoice"]["path"].lstrip("/"),
            )
            page.goto(verify_url, wait_until="domcontentloaded", timeout=35_000)
            page.wait_for_timeout(600)
            ok_login, login_msg = _timesoft_login_with_playwright(page, verify_url=verify_url)
            if not ok_login:
                context.close()
                browser.close()
                browser = None
                return False, login_msg, None

            cookies = context.cookies()
            try:
                user_agent = page.evaluate("navigator.userAgent")
            except Exception:
                user_agent = "Mozilla/5.0"
            context.close()
            browser.close()
            browser = None

        http_session = _timesoft_requests_session_from_browser_cookies(cookies, user_agent)
        return True, "Đã tạo phiên TimeSoft và chuyển session sang API trực tiếp.", http_session
    except Exception as e:
        try:
            if browser is not None:
                browser.close()
        except Exception:
            pass
        return False, f"Không tạo được phiên API TimeSoft: {type(e).__name__}: {e}", None


def _timesoft_get_http_session(force_login=False):
    key_session = "_timesoft_http_session_v81"
    key_time = "_timesoft_http_session_time_v81"
    now_ts = time.time()
    if not force_login:
        existing = st.session_state.get(key_session)
        created_at = float(st.session_state.get(key_time, 0) or 0)
        if existing is not None and (now_ts - created_at) < TIMESOFT_HTTP_SESSION_TTL_SECONDS:
            return True, "Đang dùng lại phiên TimeSoft còn hiệu lực.", existing

    ok, msg, session = _timesoft_new_authenticated_http_session()
    if ok and session is not None:
        st.session_state[key_session] = session
        st.session_state[key_time] = now_ts
    return ok, msg, session


def _timesoft_post_json(session, api_path, referer_path, payload, timeout=60):
    url = urljoin(TIMESOFT_BASE_URL + "/", str(api_path).lstrip("/"))
    referer = urljoin(TIMESOFT_BASE_URL + "/", str(referer_path).lstrip("/"))
    headers = {
        "Accept": "application/json, text/plain, */*",
        "Content-Type": "application/json;charset=UTF-8",
        "Referer": referer,
        "Origin": TIMESOFT_BASE_URL,
        "X-Requested-With": "XMLHttpRequest",
    }
    try:
        resp = session.post(url, json=payload, headers=headers, timeout=timeout, allow_redirects=True)
    except Exception as e:
        return False, f"Không gọi được TimeSoft API: {type(e).__name__}: {e}", None, False

    final_url = str(resp.url or "")
    ctype = str(resp.headers.get("content-type", "") or "").lower()
    if resp.status_code in {401, 403} or "/user/login" in final_url.lower():
        return False, "Phiên đăng nhập TimeSoft đã hết hạn.", None, True
    if resp.status_code != 200:
        return False, f"TimeSoft API HTTP {resp.status_code}.", None, False
    if "json" not in ctype:
        # Login page đôi lúc trả HTTP 200 HTML.
        body_start = str(resp.text or "")[:1000].lower()
        if "login" in final_url.lower() or "password" in body_start or "đăng nhập" in body_start:
            return False, "Phiên đăng nhập TimeSoft không còn hợp lệ.", None, True
    try:
        data = resp.json()
    except Exception:
        return False, "TimeSoft API không trả JSON hợp lệ.", None, False

    return_code = str((data or {}).get("ReturnCode", "") or "")
    if return_code and return_code != "000000":
        msg = str((data or {}).get("Message", "") or "").strip()
        return False, f"TimeSoft trả mã {return_code}: {msg or 'Không rõ lỗi'}", data, False
    return True, "OK", data, False


def _timesoft_summary_invoice_payload(start_date, end_date):
    return {
        "objectSearch": {
            "TypeData": 0,
            "TypeInvoice": 1,
            "TachInvoiceSpa": 0,
            "CreateTimeRange": _timesoft_date_range_text(start_date, end_date),
        },
        "pageSize": 0,
    }


def _timesoft_employee_checkin_payload(start_date, end_date, page_index=1, page_size=TIMESOFT_CHECKIN_PAGE_SIZE):
    return {
        "objectSearch": {
            "CreateDateRange": _timesoft_date_range_text(start_date, end_date),
        },
        "pageIndex": int(page_index),
        "pageSize": int(page_size),
    }


def _timesoft_fetch_summary_invoice(session, start_date, end_date):
    cfg = TIMESOFT_DIRECT_APIS["summary_invoice"]
    payload = _timesoft_summary_invoice_payload(start_date, end_date)
    ok, msg, data, auth_failed = _timesoft_post_json(
        session, cfg["url"], cfg["referer"], payload
    )
    if not ok:
        return False, msg, {}, pd.DataFrame(), auth_failed
    rows = (data or {}).get("Data") or []
    df = pd.json_normalize(rows, sep=".") if isinstance(rows, list) and rows else pd.DataFrame()
    summary_keys = [
        "Total", "TotalMoney", "TotalDiscount", "TotalQuantity", "TotalInvoice",
        "TotalActualRevenu", "TotalPromotion", "TotalPayment", "TotalActualTerm",
        "TotalDebt", "ReportByYear", "Message",
    ]
    meta = {k: (data or {}).get(k) for k in summary_keys if k in (data or {})}
    return True, "Đã lấy báo cáo tổng hợp doanh thu.", meta, df, False


def _timesoft_fetch_employee_checkin(session, start_date, end_date):
    cfg = TIMESOFT_DIRECT_APIS["employee_checkin"]
    all_rows = []
    total_expected = None
    for page_index in range(1, TIMESOFT_MAX_CHECKIN_PAGES + 1):
        payload = _timesoft_employee_checkin_payload(
            start_date, end_date, page_index=page_index, page_size=TIMESOFT_CHECKIN_PAGE_SIZE
        )
        ok, msg, data, auth_failed = _timesoft_post_json(
            session, cfg["url"], cfg["referer"], payload
        )
        if not ok:
            return False, msg, pd.DataFrame(), {"Total": total_expected}, auth_failed
        if total_expected is None:
            try:
                total_expected = int((data or {}).get("Total") or 0)
            except Exception:
                total_expected = 0
        page_rows = (data or {}).get("Data") or []
        if not isinstance(page_rows, list) or not page_rows:
            break
        all_rows.extend(page_rows)
        if total_expected and len(all_rows) >= total_expected:
            break

    df = pd.json_normalize(all_rows, sep=".") if all_rows else pd.DataFrame()
    meta = {"Total": total_expected if total_expected is not None else len(all_rows)}
    return True, "Đã lấy báo cáo chấm công nhân viên.", df, meta, False


def timesoft_direct_sync(start_date, end_date, force_login=False):
    """Đồng bộ trực tiếp 2 API. Nếu session hết hạn, tự đăng nhập lại và thử thêm 1 lần."""
    if not timesoft_is_configured():
        return False, "Chưa cấu hình TimeSoft trong Secrets.", {}

    last_error = ""
    for attempt in range(2):
        force_now = bool(force_login or attempt > 0)
        ok_session, session_msg, session = _timesoft_get_http_session(force_login=force_now)
        if not ok_session or session is None:
            return False, session_msg, {}

        ok_inv, msg_inv, inv_meta, inv_df, inv_auth = _timesoft_fetch_summary_invoice(
            session, start_date, end_date
        )
        if not ok_inv:
            last_error = msg_inv
            if inv_auth and attempt == 0:
                continue
            return False, msg_inv, {}

        ok_chk, msg_chk, chk_df, chk_meta, chk_auth = _timesoft_fetch_employee_checkin(
            session, start_date, end_date
        )
        if not ok_chk:
            last_error = msg_chk
            if chk_auth and attempt == 0:
                continue
            return False, msg_chk, {}

        result = {
            "start_date": start_date,
            "end_date": end_date,
            "synced_at": datetime.now(VN_TZ),
            "session_message": session_msg,
            "summary_invoice_meta": inv_meta,
            "summary_invoice_df": inv_df,
            "employee_checkin_meta": chk_meta,
            "employee_checkin_df": chk_df,
        }
        return True, (
            f"Lấy dữ liệu TimeSoft thành công: {len(inv_df)} dòng doanh thu chi tiết, "
            f"{len(chk_df)} dòng chấm công."
        ), result

    return False, last_error or "Không đồng bộ được TimeSoft.", {}


# ==========================================================
# V82 - SNAPSHOT ĐỒNG BỘ NỀN CLOUD RUN / POSTGRESQL
# ==========================================================
def _timesoft_bg_key(prefix, target_date=None):
    d = target_date if isinstance(target_date, date) else get_vn_today()
    return f"{prefix}_{d.strftime('%Y%m%d')}"


def _timesoft_read_background_snapshot(target_date=None):
    """Đọc snapshot do Cloud Run Job ghi vào PostgreSQL; không gọi TimeSoft."""
    if vpg is None or not _vpg_is_enabled():
        return {}
    d = target_date if isinstance(target_date, date) else get_vn_today()
    try:
        return {
            "date": d,
            "status": vpg.read_dataset("timesoft_background_status", allow_stale=True),
            "summary_invoice": vpg.read_dataset(_timesoft_bg_key("timesoft_summary_invoice", d), allow_stale=True),
            "summary_totals": vpg.read_dataset(_timesoft_bg_key("timesoft_summary_totals", d), allow_stale=True),
            "employee_checkin": vpg.read_dataset(_timesoft_bg_key("timesoft_employee_checkin", d), allow_stale=True),
        }
    except Exception:
        return {}


def _timesoft_background_status_row():
    snap = _timesoft_read_background_snapshot(get_vn_today())
    df = snap.get("status") if isinstance(snap, dict) else None
    if isinstance(df, pd.DataFrame) and not df.empty:
        return df.iloc[0].to_dict()
    return {}


def _timesoft_signed_arrival_minutes_v92672(row):
    """
    Chênh lệch giờ vào ca theo quy ước hiển thị V92.6.72:
    - số ÂM = vào muộn;
    - số DƯƠNG = vào sớm;
    - 0 = đúng giờ.

    Tính trực tiếp từ Check-in và Giờ bắt đầu ca để không phụ thuộc cách TimeSoft
    mã hóa TotalMinuteInGoLate. Có xử lý ca qua nửa đêm.
    """
    def _value(candidates):
        try:
            for c in candidates:
                if c in row.index:
                    v = row.get(c)
                    if v is not None and str(v).strip().casefold() not in {"", "nan", "none", "nat", "<na>"}:
                        return v
        except Exception:
            pass
        return ""

    def _minutes(v):
        m = re.search(r"(\d{1,2}):(\d{2})(?::(\d{2}))?", str(v or "").strip())
        if not m:
            return None
        return int(m.group(1)) * 60 + int(m.group(2)) + int(m.group(3) or 0) / 60.0

    start = _minutes(_value(["StartWorkTime", "WorkTimeStart", "ShiftStartTime"]))
    checkin = _minutes(_value(["MachineTimeCheckInStr", "CheckInTimeStr", "CheckInTime"]))
    if start is None or checkin is None:
        # Fallback: TimeSoft có thể chỉ trả tổng số phút đi trễ. Khi đó vẫn biểu diễn
        # đúng quy ước dấu âm; trường hợp vào sớm cần đủ giờ ca + check-in để tính.
        late_raw = _value([
            "TotalMinuteInGoLate", "TotalMinuteGoLate", "MinuteInGoLate",
            "GoLateMinute", "LateMinute"
        ])
        try:
            if str(late_raw).strip() != "":
                late = max(0.0, float(str(late_raw).replace(",", ".").strip()))
                return -int(round(late))
        except Exception:
            pass
        return ""

    diff = checkin - start  # dương = thực tế muộn hơn ca
    if diff < -12 * 60:
        diff += 24 * 60
    elif diff > 12 * 60:
        diff -= 24 * 60
    return int(round(-diff))


def _strip_midshift_status_icons_v92673(value):
    """Trạng thái nghỉ giữa ca chỉ giữ chữ, bỏ icon/emoji trang trí."""
    text = str(value or "").strip()
    for token in [
        "✅", "🔴", "❌", "⚠️", "⚠", "🟢", "🟡", "⛔", "☕", "⏳",
        "✔️", "✔", "✖️", "✖", "ℹ️", "ℹ",
    ]:
        text = text.replace(token, "")
    text = re.sub(r"\s+", " ", text).strip(" ·-–—")
    return text


def _timesoft_checkin_display_df(
    df,
    include_midshift_break=True,
    raw_punch_df=None,
    tour_df=None,
):
    """
    V92.6.67 - Bảng chấm công Snapshot + theo dõi nghỉ giữa ca.

    Bổ sung theo dõi nghỉ giữa ca và chênh lệch giờ vào:
      - Giờ ra nghỉ giữa ca
      - Giờ vào lại
      - Số phút nghỉ giữa ca
      - Trạng thái nghỉ giữa ca
      - Số phút (âm = vào muộn, dương = vào sớm)

    Nguồn xác định V92.6.73:
      1) TimeSoft trước: FaceID chi tiết; nếu không đủ thì dữ liệu TimeSoft tổng hợp;
      2) CHỈ khi TimeSoft không đủ dữ liệu để xác định đủ cặp ra/vào mới fallback
         sang TourVera R:V hoặc nguồn đối chiếu khác. Không để nguồn phụ ghi đè TimeSoft.

    FaceID trong khung 23:00 ngày làm việc -> 02:00 ngày hôm sau được coi là
    check-out cuối ca và KHÔNG dùng làm cặp nghỉ giữa ca.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    # V92.6.72: mọi danh sách vận hành chỉ hiển thị nhân sự Đang làm việc.
    # Dữ liệu nguồn không bị xóa; chỉ lọc lớp hiển thị.
    try:
        _status_map_v92672 = load_employment_status_map()
        _name_col_v92672 = next((c for c in [
            "employeeInfo.Name", "EmployeeName", "Tên nhân viên", "Nhân viên", "Name"
        ] if c in df.columns), None)
        if _name_col_v92672 and _status_map_v92672:
            _active_v92672 = globals().get("EMPLOYMENT_STATUS_ACTIVE", "Đang làm việc")
            _mask_v92672 = df[_name_col_v92672].astype(str).apply(
                lambda x: _status_map_v92672.get(normalize_login_name(x), _active_v92672) == _active_v92672
            )
            df = df[_mask_v92672].copy()
            if df.empty:
                return pd.DataFrame()
    except Exception:
        pass

    preferred = [
        "WorkDateStr",
        "employeeInfo.EmployeeCode",
        "employeeInfo.Name",
        "WorkTimeName",
        "StartWorkTime",
        "EndWorkTime",
        "MachineTimeCheckInStr",
        "MachineTimeCheckOutStr",
        "GoWorkTypeName",
        "LastCheckInTypeName",
        "TotalMinuteInGoLate",
        "TotalMinuteBackHomeEarly",
        "TotalMinuteInDay",
        "TotalCheckInOneDay",
    ]
    cols = [c for c in preferred if c in df.columns]
    out = df[cols].copy() if cols else df.copy()
    rename = {
        "WorkDateStr": "Ngày",
        "employeeInfo.EmployeeCode": "Mã NV",
        "employeeInfo.Name": "Nhân viên",
        "WorkTimeName": "Ca",
        "StartWorkTime": "Giờ bắt đầu ca",
        "EndWorkTime": "Giờ kết thúc ca",
        "MachineTimeCheckInStr": "Check-in",
        "MachineTimeCheckOutStr": "FaceID cuối TimeSoft",
        "GoWorkTypeName": "Trạng thái vào",
        "LastCheckInTypeName": "Trạng thái ra",
        "TotalMinuteInGoLate": "Phút đi trễ",
        "TotalMinuteBackHomeEarly": "Phút về sớm",
        "TotalMinuteInDay": "Tổng phút trong ngày",
        "TotalCheckInOneDay": "Số lần check-in",
    }
    out = out.rename(columns=rename)

    # V92.6.67: TimeSoft SearchElastic đặt mốc FaceID cuối vào field CheckOut,
    # nhưng ở VERA mốc trước 23:00 thường là FaceID giữa ca chứ không phải về cuối ngày.
    # Chỉ công nhận check-out cuối ca nếu nằm trong cửa sổ 23:00 -> 02:00 hôm sau.
    if "FaceID cuối TimeSoft" in out.columns:
        _checkout_end_v92667 = []
        for _, _raw_checkout_v92667 in df.iterrows():
            _work_date_checkout_v92667 = _timesoft_work_date_from_row(_raw_checkout_v92667)
            _checkout_raw_v92667 = _timesoft_row_value(
                _raw_checkout_v92667,
                ["MachineTimeCheckOutStr", "CheckOutTimeStr", "CheckOutTime"],
            )
            _checkout_dt_v92667 = None
            try:
                _parsed_checkout_v92667 = pd.to_datetime(
                    _checkout_raw_v92667, errors="coerce", dayfirst=True
                )
                if not pd.isna(_parsed_checkout_v92667):
                    _checkout_dt_v92667 = pd.Timestamp(_parsed_checkout_v92667).to_pydatetime()
                    if _checkout_dt_v92667.tzinfo is None:
                        _checkout_dt_v92667 = _checkout_dt_v92667.replace(tzinfo=VN_TZ)
            except Exception:
                _checkout_dt_v92667 = None
            if _is_end_shift_checkout_v92667(
                _checkout_dt_v92667, _work_date_checkout_v92667
            ):
                _checkout_end_v92667.append(
                    _checkout_dt_v92667.strftime("%d/%m/%Y %H:%M:%S")
                )
            else:
                _checkout_end_v92667.append("")

        _face_last_pos_v92667 = out.columns.get_loc("FaceID cuối TimeSoft") + 1
        out.insert(
            _face_last_pos_v92667,
            "Check-out cuối ca",
            _checkout_end_v92667,
        )

    if include_midshift_break:
        out["Giờ ra nghỉ giữa ca"] = ""
        out["Giờ vào lại"] = ""
        out["Số phút nghỉ giữa ca"] = ""
        out["Trạng thái nghỉ giữa ca"] = ""
        try:
            # FaceID chi tiết được nạp thủ công từ trang Snapshot/Đồng bộ TimeSoft.
            if raw_punch_df is None:
                _raw_session_v92667 = st.session_state.get(
                    "timesoft_raw_faceid_df_v92667"
                )
                if isinstance(_raw_session_v92667, pd.DataFrame):
                    raw_punch_df = _raw_session_v92667

            # TourVera là nguồn đối chiếu hiện trường. load_bang_tour_input đã cache 300 giây.
            if tour_df is None:
                try:
                    _tour_v92667, _tour_err_v92667 = load_bang_tour_input()
                    if isinstance(_tour_v92667, pd.DataFrame) and not _tour_v92667.empty:
                        tour_df = _tour_v92667
                except Exception:
                    tour_df = None

            _cred_break_v92667 = load_credentials_recent()
            _break_df_v92667 = calculate_midshift_break_from_timesoft(
                df,
                _cred_break_v92667,
                raw_punch_df=raw_punch_df,
                tour_df=tour_df,
            )

            if isinstance(_break_df_v92667, pd.DataFrame) and not _break_df_v92667.empty:
                _break_map_v92667 = {}
                for _, _br_v92667 in _break_df_v92667.iterrows():
                    _br_name_v92667 = normalize_login_name(
                        _br_v92667.get("Tên nhân viên", "")
                    )
                    _br_date_v92667 = pd.to_datetime(
                        _br_v92667.get("Ngày", ""), errors="coerce", dayfirst=True
                    )
                    if not _br_name_v92667 or pd.isna(_br_date_v92667):
                        continue
                    _break_map_v92667[(
                        _br_name_v92667,
                        _br_date_v92667.date().isoformat(),
                    )] = {
                        "out": str(_br_v92667.get("Bắt đầu nghỉ", "") or ""),
                        "in": str(_br_v92667.get("Kết thúc nghỉ", "") or ""),
                        "minutes": _br_v92667.get("Số phút nghỉ giữa ca", ""),
                        "status": str(_br_v92667.get("Trạng thái", "") or ""),
                    }

                _vals_out, _vals_in, _vals_min, _vals_status = [], [], [], []
                for _, _raw_v92667 in df.iterrows():
                    _name_v92667 = str(_timesoft_row_value(
                        _raw_v92667,
                        [
                            "employeeInfo.Name", "EmployeeName",
                            "Tên nhân viên", "Nhân viên", "Name",
                        ],
                    ) or "").strip()
                    _work_date_v92667 = _timesoft_work_date_from_row(_raw_v92667)
                    _key_v92667 = (
                        normalize_login_name(_name_v92667),
                        _work_date_v92667.isoformat()
                        if isinstance(_work_date_v92667, date) else "",
                    )
                    _info_v92667 = _break_map_v92667.get(_key_v92667, {})
                    _vals_out.append(_info_v92667.get("out", ""))
                    _vals_in.append(_info_v92667.get("in", ""))
                    _vals_min.append(_info_v92667.get("minutes", ""))
                    _vals_status.append(
                        _strip_midshift_status_icons_v92673(
                            _info_v92667.get("status", "")
                        )
                    )

                if len(_vals_out) == len(out):
                    out["Giờ ra nghỉ giữa ca"] = _vals_out
                    out["Giờ vào lại"] = _vals_in
                    out["Số phút nghỉ giữa ca"] = _vals_min
                    out["Trạng thái nghỉ giữa ca"] = _vals_status
        except Exception:
            # Chấm công chính vẫn phải hiển thị khi nguồn đối chiếu tạm lỗi.
            pass

    # V92.6.72: cột cuối cùng theo quy ước Âm = vào muộn, Dương = vào sớm.
    try:
        out["Số phút"] = [
            _timesoft_signed_arrival_minutes_v92672(row) for _, row in df.iterrows()
        ]
    except Exception:
        out["Số phút"] = ""

    return out



def _timesoft_snapshot_storage_status_df():
    """Danh sách dataset TimeSoft đang có trong PostgreSQL."""
    if vpg is None or not _vpg_is_enabled():
        return pd.DataFrame()
    try:
        df = vpg.get_status()
        if not isinstance(df, pd.DataFrame) or df.empty or "dataset_key" not in df.columns:
            return pd.DataFrame()
        out = df[df["dataset_key"].astype(str).str.startswith("timesoft_")].copy()
        if out.empty:
            return out
        def _extract_date(key):
            m = re.search(r"_(\d{8})$", str(key or ""))
            if not m:
                return pd.NaT
            try:
                return pd.to_datetime(m.group(1), format="%Y%m%d", errors="coerce")
            except Exception:
                return pd.NaT
        out["snapshot_date"] = out["dataset_key"].apply(_extract_date)
        return out.sort_values(["snapshot_date", "dataset_key"], ascending=[False, True], na_position="last")
    except Exception:
        return pd.DataFrame()


def _timesoft_available_snapshot_dates():
    """Ngày snapshot thực sự đang tồn tại trong PostgreSQL."""
    df = _timesoft_snapshot_storage_status_df()
    if df.empty:
        return []
    mask = df["dataset_key"].astype(str).str.match(
        r"^timesoft_(summary_invoice|summary_totals|employee_checkin)_\d{8}$",
        na=False,
    )
    dates = []
    for value in df.loc[mask, "snapshot_date"].dropna().tolist():
        try:
            dates.append(pd.Timestamp(value).date())
        except Exception:
            pass
    return sorted(set(dates))


def _timesoft_collect_checkin_range_v92686(start_date, end_date):
    """V92.6.86 - Chỉ đọc dataset chấm công TimeSoft trong khoảng được chọn.

    Không tải summary_invoice/summary_totals vì màn hình Kiểm tra nghỉ giữa ca chỉ cần
    employee_checkin. Mỗi ngày snapshot chỉ đọc 1 dataset PostgreSQL.
    """
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        return [], pd.DataFrame()
    if start_date > end_date:
        start_date, end_date = end_date, start_date

    available = [
        d for d in _timesoft_available_snapshot_dates()
        if start_date <= d <= end_date
    ]
    if not available or vpg is None or not _vpg_is_enabled():
        return available, pd.DataFrame()

    frames = []
    for d in available:
        try:
            chk = vpg.read_dataset(
                _timesoft_bg_key("timesoft_employee_checkin", d),
                allow_stale=True,
            )
        except Exception:
            chk = pd.DataFrame()
        if not isinstance(chk, pd.DataFrame) or chk.empty:
            continue
        x = chk.copy()
        # Chỉ bổ sung ngày snapshot để người dùng dễ đối chiếu; engine vẫn ưu tiên
        # WorkDate/WorkDateStr của TimeSoft khi chúng tồn tại.
        if "Ngày snapshot" not in x.columns:
            x.insert(0, "Ngày snapshot", d.strftime("%d/%m/%Y"))
        frames.append(x)

    return available, (
        pd.concat(frames, ignore_index=True, sort=False)
        if frames else pd.DataFrame()
    )


def _timesoft_snapshot_events(start_date, end_date, limit=5000):
    """Lịch sử hoạt động PostgreSQL. Hỗ trợ helper mới; helper cũ thì trả bảng rỗng."""
    if vpg is None or not _vpg_is_enabled():
        return pd.DataFrame()
    fn = getattr(vpg, "get_sync_events", None)
    if not callable(fn):
        return pd.DataFrame()
    try:
        start_dt = datetime.combine(start_date, datetime.min.time()).replace(tzinfo=VN_TZ)
        end_dt = datetime.combine(end_date + timedelta(days=1), datetime.min.time()).replace(tzinfo=VN_TZ)
        df = fn(
            dataset_prefix="timesoft_",
            start_at=start_dt,
            end_at=end_dt,
            limit=max(100, min(int(limit), 20000)),
        )
        if not isinstance(df, pd.DataFrame):
            return pd.DataFrame()
        return df
    except Exception:
        return pd.DataFrame()


def _timesoft_collect_snapshot_history(start_date, end_date):
    """Gộp các snapshot theo ngày trong khoảng đã chọn."""
    available = [d for d in _timesoft_available_snapshot_dates() if start_date <= d <= end_date]
    summary_rows = []
    invoice_frames = []
    checkin_frames = []

    for d in available:
        snap = _timesoft_read_background_snapshot(d)
        inv = snap.get("summary_invoice") if isinstance(snap, dict) else None
        totals = snap.get("summary_totals") if isinstance(snap, dict) else None
        chk = snap.get("employee_checkin") if isinstance(snap, dict) else None

        inv_count = len(inv) if isinstance(inv, pd.DataFrame) else 0
        chk_count = len(chk) if isinstance(chk, pd.DataFrame) else 0

        tr = {}
        if isinstance(totals, pd.DataFrame) and not totals.empty:
            tr = totals.iloc[0].to_dict()

        summary_rows.append({
            "Ngày": d.strftime("%d/%m/%Y"),
            "Doanh thu · dòng": inv_count,
            "Chấm công · dòng": chk_count,
            "Tổng tiền": float(tr.get("TotalMoney", 0) or 0),
            "Giảm giá": float(tr.get("TotalDiscount", 0) or 0),
            "Doanh thu thực": float(tr.get("TotalActualRevenu", 0) or 0),
        })

        if isinstance(inv, pd.DataFrame) and not inv.empty:
            x = inv.copy()
            x.insert(0, "Ngày snapshot", d.strftime("%d/%m/%Y"))
            invoice_frames.append(x)

        if isinstance(chk, pd.DataFrame) and not chk.empty:
            x = chk.copy()
            x.insert(0, "Ngày snapshot", d.strftime("%d/%m/%Y"))
            checkin_frames.append(x)

    summary_df = pd.DataFrame(summary_rows)
    invoice_df = pd.concat(invoice_frames, ignore_index=True, sort=False) if invoice_frames else pd.DataFrame()
    checkin_df = pd.concat(checkin_frames, ignore_index=True, sort=False) if checkin_frames else pd.DataFrame()
    return available, summary_df, invoice_df, checkin_df



def _excel_safe_dataframe_v92654(df):
    """
    V92.6.54 - Excel không hỗ trợ datetime có timezone.
    Chuyển mọi cột datetime timezone-aware về datetime naive theo giờ đang hiển thị,
    đồng thời xử lý object column có Timestamp/datetime timezone-aware.
    """
    if not isinstance(df, pd.DataFrame):
        return pd.DataFrame()

    out = df.copy()

    for col in out.columns:
        s = out[col]

        # Datetime dtype có timezone: bỏ timezone, giữ nguyên giờ địa phương đang hiển thị.
        try:
            if isinstance(s.dtype, pd.DatetimeTZDtype):
                out[col] = s.dt.tz_localize(None)
                continue
        except Exception:
            pass

        # Object dtype đôi khi chứa Timestamp/datetime có tz.
        if getattr(s, "dtype", None) == object:
            def _strip_tz_excel_v92654(v):
                try:
                    if isinstance(v, pd.Timestamp):
                        if v.tzinfo is not None:
                            return v.tz_localize(None)
                        return v
                    if isinstance(v, datetime):
                        if v.tzinfo is not None:
                            return v.replace(tzinfo=None)
                        return v
                except Exception:
                    pass
                return v
            out[col] = s.map(_strip_tz_excel_v92654)

    return out



SNAPSHOT_RANGE_PRESETS_V92657 = [
    "Hôm qua",
    "Hôm nay",
    "Tuần trước",
    "Tuần này",
    "Tháng trước",
    "Tháng này",
    "Tất cả",
    "Tùy chỉnh",
]


def _snapshot_preset_range_v92657(preset, today, earliest=None, latest=None):
    """V92.6.65 - khoảng ngày cho dropdown Snapshot."""
    preset = str(preset or "").strip()
    if preset == "Hôm qua":
        d = today - timedelta(days=1)
        return d, d
    if preset == "Hôm nay":
        return today, today
    if preset == "Tuần trước":
        this_monday = today - timedelta(days=today.weekday())
        prev_monday = this_monday - timedelta(days=7)
        return prev_monday, prev_monday + timedelta(days=6)
    if preset == "Tuần này":
        monday = today - timedelta(days=today.weekday())
        return monday, today
    if preset == "Tháng trước":
        prev_end = today.replace(day=1) - timedelta(days=1)
        return prev_end.replace(day=1), prev_end
    if preset == "Tháng này":
        return today.replace(day=1), today
    if preset == "Tất cả":
        start = earliest if isinstance(earliest, date) else today
        end = latest if isinstance(latest, date) else today
        if start > end:
            start, end = end, start
        return start, end
    return None, None


def _snapshot_custom_range_changed_v92657():
    """Khi user chỉnh calendar, chuyển preset sang Tùy chỉnh ở lượt rerun kế tiếp."""
    try:
        st.session_state["snapshot_history_preset_v92657"] = "Tùy chỉnh"
    except Exception:
        pass


def _style_snapshot_excel_v92657(writer):
    """
    Format workbook Snapshot:
    - dòng tiêu đề nền #1890FF, chữ trắng đậm;
    - AutoFilter;
    - cố định dòng tiêu đề;
    - fit độ rộng cột.
    """
    try:
        from openpyxl.styles import PatternFill, Font, Alignment
        from openpyxl.utils import get_column_letter
    except Exception:
        return

    header_fill = PatternFill(fill_type="solid", fgColor="1890FF")
    header_font = Font(color="FFFFFF", bold=True)
    header_alignment = Alignment(horizontal="center", vertical="center")

    for ws in writer.book.worksheets:
        if ws.max_row < 1 or ws.max_column < 1:
            continue

        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = header_alignment

        ws.freeze_panes = "A2"
        ws.auto_filter.ref = ws.dimensions

        for col_idx in range(1, ws.max_column + 1):
            max_len = 0
            for row_idx in range(1, ws.max_row + 1):
                value = ws.cell(row=row_idx, column=col_idx).value
                if value is None:
                    continue
                display = str(value)
                if "\n" in display:
                    display = max(display.splitlines(), key=len, default="")
                max_len = max(max_len, len(display))

            width = min(max(max_len + 2, 10), 45)
            ws.column_dimensions[get_column_letter(col_idx)].width = width


def _timesoft_history_export_workbook(summary_df, checkin_df, start_date, end_date):
    """
    V92.6.57 - Export Snapshot chỉ giữ 3 sheet:
    ThongTin, TongHopNgay, ChamCong.
    """
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        info = pd.DataFrame([
            {"Thông tin": "Từ ngày", "Giá trị": start_date.strftime("%d/%m/%Y")},
            {"Thông tin": "Đến ngày", "Giá trị": end_date.strftime("%d/%m/%Y")},
            {"Thông tin": "Ngày export", "Giá trị": datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")},
            {
                "Thông tin": "Số ngày có snapshot",
                "Giá trị": len(summary_df) if isinstance(summary_df, pd.DataFrame) else 0,
            },
            {
                "Thông tin": "Dòng chấm công",
                "Giá trị": len(checkin_df) if isinstance(checkin_df, pd.DataFrame) else 0,
            },
        ])

        _excel_safe_dataframe_v92654(info).to_excel(
            writer, index=False, sheet_name="ThongTin"
        )

        _excel_safe_dataframe_v92654(
            summary_df if isinstance(summary_df, pd.DataFrame) else pd.DataFrame()
        ).to_excel(
            writer, index=False, sheet_name="TongHopNgay"
        )

        chk_export = (
            _timesoft_checkin_display_df(checkin_df)
            if isinstance(checkin_df, pd.DataFrame)
            else pd.DataFrame()
        )
        if (
            isinstance(checkin_df, pd.DataFrame)
            and "Ngày snapshot" in checkin_df.columns
            and "Ngày snapshot" not in chk_export.columns
        ):
            chk_export.insert(0, "Ngày snapshot", checkin_df["Ngày snapshot"].values)

        _excel_safe_dataframe_v92654(chk_export).to_excel(
            writer, index=False, sheet_name="ChamCong"
        )

        _style_snapshot_excel_v92657(writer)

    return output.getvalue()



def render_timesoft_snapshot_history_admin():
    """V92.6.65 - Admin: dropdown thời gian + Snapshot chấm công có nghỉ giữa ca."""
    if str(st.session_state.get("current_role", "")).strip().lower() != "admin":
        return

    if vpg is None or not _vpg_is_enabled():
        st.warning(
            "PostgreSQL chưa được bật nên chưa thể đọc lịch sử snapshot. "
            "Khi PostgreSQL/Cloud SQL hoạt động, trang này sẽ tự đọc dữ liệu đã lưu."
        )
        return

    today = get_vn_today()
    available_dates = _timesoft_available_snapshot_dates()

    if available_dates:
        earliest = min(available_dates)
        latest = max(available_dates)
    else:
        earliest = today
        latest = today

    st.markdown("### 🔎 Bộ lọc thời gian")

    if "snapshot_history_preset_v92657" not in st.session_state:
        st.session_state["snapshot_history_preset_v92657"] = "Hôm nay"
    elif st.session_state.get("snapshot_history_preset_v92657") not in SNAPSHOT_RANGE_PRESETS_V92657:
        # Tương thích session cũ V92.6.57-64 (7 ngày trước/14 ngày trước/Năm...).
        st.session_state["snapshot_history_preset_v92657"] = "Hôm nay"

    # V92.6.65: dropdown thay radio để tiết kiệm chiều cao giao diện.
    preset_col, calendar_col = st.columns([1.35, 3.65])

    with preset_col:
        snapshot_preset = st.selectbox(
            "Chọn nhanh",
            SNAPSHOT_RANGE_PRESETS_V92657,
            key="snapshot_history_preset_v92657",
            filter_mode="contains",
        )

    preset_start, preset_end = _snapshot_preset_range_v92657(
        snapshot_preset,
        today,
        earliest=earliest,
        latest=latest,
    )

    # Khi đổi preset, cập nhật lại khoảng ngày đang hiển thị.
    last_preset = st.session_state.get("_snapshot_history_last_preset_v92657")
    if snapshot_preset != "Tùy chỉnh" and last_preset != snapshot_preset:
        st.session_state["snapshot_history_range_v92657"] = (preset_start, preset_end)
        st.session_state["_snapshot_history_last_preset_v92657"] = snapshot_preset

    default_range_v92657 = st.session_state.get(
        "snapshot_history_range_v92657",
        (
            max(earliest, today - timedelta(days=6)),
            latest if available_dates else today,
        ),
    )

    with calendar_col:
        selected_range = st.date_input(
            "📅 Khoảng thời gian",
            value=default_range_v92657,
            min_value=today - timedelta(days=3650),
            max_value=today,
            format="DD/MM/YYYY",
            key="snapshot_history_range_v92657",
            on_change=_snapshot_custom_range_changed_v92657,
        )

    if isinstance(selected_range, (tuple, list)):
        if len(selected_range) >= 2:
            start_date, end_date = selected_range[0], selected_range[1]
        elif len(selected_range) == 1:
            start_date = end_date = selected_range[0]
        else:
            start_date = end_date = today
    else:
        start_date = end_date = selected_range or today

    if start_date > end_date:
        start_date, end_date = end_date, start_date

    st.session_state["snapshot_history_start"] = start_date
    st.session_state["snapshot_history_end"] = end_date

    if start_date > end_date:
        st.error("Ngày bắt đầu phải nhỏ hơn hoặc bằng ngày kết thúc.")
        return

    if (end_date - start_date).days > 3650:
        st.warning("Khoảng lọc tối đa là 10 năm.")
        return

    available, summary_df, _invoice_df_unused, checkin_df = _timesoft_collect_snapshot_history(
        start_date, end_date
    )

    m1, m2, m3 = st.columns(3)
    m1.metric("Ngày có snapshot", len(available))
    m2.metric("Dòng chấm công", len(checkin_df))

    if not summary_df.empty and "Doanh thu thực" in summary_df.columns:
        total_actual = float(
            pd.to_numeric(summary_df["Doanh thu thực"], errors="coerce").fillna(0).sum()
        )
    else:
        total_actual = 0.0

    m3.metric(
        "Tổng doanh thu thực",
        f"{total_actual:,.0f} đ".replace(",", "."),
    )

    export_bytes = _timesoft_history_export_workbook(
        summary_df, checkin_df, start_date, end_date
    )
    st.download_button(
        "📥 Export lịch sử Snapshot · Excel",
        data=export_bytes,
        disabled=not action_access("snapshot_export"),
        file_name=f"VERA_SNAPSHOT_{start_date.strftime('%Y%m%d')}_{end_date.strftime('%Y%m%d')}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        use_container_width=True,
        key="export_snapshot_history_xlsx",
    )

    tab_chk, tab_summary = st.tabs([
        "🕒 Chấm công",
        "📊 Tổng hợp theo ngày",
    ])

    with tab_summary:
        if summary_df.empty:
            st.info("Không có snapshot trong khoảng thời gian đã chọn.")
        else:
            view = summary_df.copy()
            for c in ["Tổng tiền", "Giảm giá", "Doanh thu thực"]:
                view[c] = pd.to_numeric(view[c], errors="coerce").fillna(0).map(
                    lambda x: f"{float(x):,.0f} đ".replace(",", ".")
                )
            st.dataframe(view, hide_index=True, width="stretch", height=420)

    with tab_chk:
        if checkin_df.empty:
            st.info("Không có dữ liệu chấm công trong khoảng đã chọn.")
        else:
            chk_view = _timesoft_checkin_display_df(checkin_df)
            if "Ngày snapshot" in checkin_df.columns and "Ngày snapshot" not in chk_view.columns:
                chk_view.insert(0, "Ngày snapshot", checkin_df["Ngày snapshot"].values)

            # Lọc nhân viên ngay trong chấm công lịch sử.
            employee_col = None
            for candidate in ["Nhân viên", "employeeInfo.Name", "Tên nhân viên"]:
                if candidate in chk_view.columns:
                    employee_col = candidate
                    break
            if employee_col:
                names = sorted(
                    [str(x).strip() for x in chk_view[employee_col].dropna().unique().tolist() if str(x).strip()],
                    key=lambda x: normalize_login_name(x),
                )
                selected_employee = st.selectbox(
                    "Nhân viên",
                    ["Tất cả"] + names,
                    key="snapshot_history_employee_filter",
                )
                if selected_employee != "Tất cả":
                    chk_view = chk_view[chk_view[employee_col].astype(str).eq(selected_employee)].copy()
            st.caption(
                "☕ Nghỉ giữa ca: Giờ ra / Giờ vào lại / Trạng thái được tính từ các cụm FaceID "
                "theo cùng quy tắc đang dùng cho Auto Update, ưu tiên TimeSoft trước mọi nguồn khác. · Số phút: số âm = vào muộn, "
                "số dương = vào sớm."
            )
            st.dataframe(chk_view, hide_index=True, width="stretch", height=520)



def render_timesoft_background_snapshot_today(show_status=True):
    """Hiển thị snapshot TimeSoft nền hôm nay. Chỉ Admin được phép gọi/nhìn thấy."""
    if str(st.session_state.get("current_role", "")).strip().lower() != "admin":
        return

    if vpg is None or not _vpg_is_enabled():
        st.warning(
            "PostgreSQL chưa được bật nên chưa thể đọc snapshot nền. "
            "Trên Cloud Run cần bật PostgreSQL/Cloud SQL và để Cloud Scheduler chạy Job."
        )
        return

    bg_status = _timesoft_background_status_row()
    if show_status:
        if bg_status:
            bg_ok = str(bg_status.get("status", "")).lower() == "success"
            last_sync = str(bg_status.get("synced_at_vn", "") or bg_status.get("synced_at", ""))
            (st.success if bg_ok else st.warning)(
                f"{'✅' if bg_ok else '⚠️'} Cloud Run Job: {bg_status.get('status', 'unknown')} · "
                f"lần chạy gần nhất {last_sync or 'chưa rõ'}"
            )
            b1, b2, b3, b4 = st.columns(4)
            b1.metric("Chu kỳ", f"{TIMESOFT_BACKGROUND_INTERVAL_MINUTES} phút")
            b2.metric("Doanh thu · dòng", int(float(bg_status.get("invoice_rows", 0) or 0)))
            b3.metric("Chấm công · dòng", int(float(bg_status.get("checkin_rows", 0) or 0)))
            b4.metric("Thời gian chạy", f"{float(bg_status.get('duration_seconds', 0) or 0):.1f}s")
        else:
            st.info(
                "PostgreSQL đã bật nhưng chưa có snapshot TimeSoft nền. "
                "Sau khi Cloud Scheduler gọi Cloud Run Job thành công lần đầu, dữ liệu sẽ xuất hiện tại đây."
            )

    bg_date = get_vn_today()
    bg_snap = _timesoft_read_background_snapshot(bg_date)

    # V92.6.72: Snapshot ưu tiên Chấm công trước.
    bg_chk = bg_snap.get("employee_checkin") if isinstance(bg_snap, dict) else None
    bg_chk_view = _timesoft_checkin_display_df(bg_chk)
    if isinstance(bg_chk_view, pd.DataFrame) and not bg_chk_view.empty:
        st.caption("Chấm công Snapshot")
        st.dataframe(bg_chk_view, width="stretch", hide_index=True, height=420)
        st.caption("Số phút: số âm = vào muộn · số dương = vào sớm.")
    else:
        st.info("Chưa có dữ liệu chấm công Snapshot.")

    bg_tot = bg_snap.get("summary_totals") if isinstance(bg_snap, dict) else None
    if isinstance(bg_tot, pd.DataFrame) and not bg_tot.empty:
        tr = bg_tot.iloc[0].to_dict()
        t1, t2, t3 = st.columns(3)
        t1.metric("Tổng tiền", f"{float(tr.get('TotalMoney', 0) or 0):,.0f} đ".replace(",", "."))
        t2.metric("Giảm giá", f"{float(tr.get('TotalDiscount', 0) or 0):,.0f} đ".replace(",", "."))
        t3.metric("Doanh thu thực", f"{float(tr.get('TotalActualRevenu', 0) or 0):,.0f} đ".replace(",", "."))

    bg_inv = bg_snap.get("summary_invoice") if isinstance(bg_snap, dict) else None
    if isinstance(bg_inv, pd.DataFrame) and not bg_inv.empty:
        st.caption("Doanh thu Snapshot")
        st.dataframe(bg_inv, width="stretch", hide_index=True, height=300)
    else:
        st.info("Chưa có dữ liệu doanh thu Snapshot.")


def _timesoft_export_workbook(sync_result):
    output = io.BytesIO()
    inv_df = sync_result.get("summary_invoice_df")
    chk_df = sync_result.get("employee_checkin_df")
    inv_meta = sync_result.get("summary_invoice_meta") or {}
    chk_meta = sync_result.get("employee_checkin_meta") or {}
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        summary_rows = []
        for k, v in inv_meta.items():
            summary_rows.append({"Nhóm": "Doanh thu", "Chỉ số": k, "Giá trị": v})
        for k, v in chk_meta.items():
            summary_rows.append({"Nhóm": "Chấm công", "Chỉ số": k, "Giá trị": v})
        pd.DataFrame(summary_rows).to_excel(writer, index=False, sheet_name="TongHop")
        (inv_df if isinstance(inv_df, pd.DataFrame) else pd.DataFrame()).to_excel(
            writer, index=False, sheet_name="DoanhThu"
        )
        (chk_df if isinstance(chk_df, pd.DataFrame) else pd.DataFrame()).to_excel(
            writer, index=False, sheet_name="ChamCong"
        )
    return output.getvalue()


# --- CHUẨN HÓA TÊN / TÀI KHOẢN ---
def normalize_name(name):
    """Đồng nhất cách gõ Thúy/Thuý để tránh lỗi so sánh dữ liệu nghiệp vụ."""
    return str(name).replace("Thuý", "Thúy").replace("thuý", "thúy").strip()

def remove_vietnamese_accents(value):
    """Bỏ dấu tiếng Việt nhưng vẫn giữ nguyên số 0 đầu chuỗi và ký tự khác."""
    text = unicodedata.normalize("NFD", str(value))
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    return text.replace("đ", "d").replace("Đ", "D")

def normalize_login_name(value):
    """Tên đăng nhập: không phân biệt dấu, HOA/thường; không ép kiểu số."""
    return " ".join(remove_vietnamese_accents(str(value)).strip().split()).casefold()

def clean_employee_match_name(value):
    """
    Tên dùng để ĐỐI CHIẾU dữ liệu nhân viên giữa Bảng tour / TimeSoft / Google Sheet.
    Dấu * ở cuối tên trong Bảng tour chỉ là ký hiệu vận hành, không phải một phần tên nhân viên.
    Ví dụ: ``Cẩm Nhung *`` == ``Cẩm Nhung``.
    Không dùng hàm này để thay đổi tên đăng nhập hiển thị/lưu hồ sơ.
    """
    text = normalize_name(value)
    text = re.sub(r"\s*\*+\s*$", "", str(text)).strip()
    return " ".join(text.split())

def normalize_employee_match_name(value):
    return normalize_login_name(clean_employee_match_name(value))

def sort_employee_names(values, include_inactive=False):
    """
    Sắp xếp tên nhân viên A→Z, bỏ trùng.

    V92.6.72: mặc định chỉ trả nhân sự ``Đang làm việc`` để mọi dropdown/danh sách
    vận hành tự ẩn người ``Tạm thời nghỉ việc`` hoặc ``Đã nghỉ việc``.
    ``include_inactive=True`` chỉ dành cho màn hình quản trị trạng thái để Admin còn
    có thể đưa một nhân sự trở lại trạng thái Đang làm việc.
    """
    by_key = {}
    for value in values or []:
        name = str(value or "").strip()
        if not name:
            continue
        key = normalize_login_name(name)
        if key and key not in by_key:
            by_key[key] = name

    if not include_inactive and by_key:
        try:
            status_map = load_employment_status_map()
            active_status = globals().get("EMPLOYMENT_STATUS_ACTIVE", "Đang làm việc")
            by_key = {
                key: name for key, name in by_key.items()
                if status_map.get(key, active_status) == active_status
            }
        except Exception:
            pass

    return sorted(by_key.values(), key=lambda x: normalize_login_name(x))

def password_matches(input_password, stored_password):
    """Mật khẩu được so sánh đúng ký tự, có phân biệt HOA/thường và chấp nhận ký tự đặc biệt/0 đầu."""
    return hmac.compare_digest(str(input_password), str(stored_password))

def is_locked_value(value):
    return str(value).strip().casefold() in {"1", "true", "yes", "y", "khóa", "khoa", "locked", "x"}

def clean_leave_reason_display(value):
    """Làm sạch tên lý do nghỉ để hiển thị/dropdown luôn khớp chính xác."""
    text = str(value or "").replace("🔴", "").strip()
    return " ".join(text.split())

def normalize_leave_reason(value):
    """Chuẩn hóa loại nghỉ để so sánh trùng dữ liệu ổn định."""
    return clean_leave_reason_display(value).casefold()

PROGRESSIVE_PENALTY_REASONS = {
    normalize_login_name("Nghỉ không phép"): "Nghỉ không phép",
    normalize_login_name("Đi trễ không phép"): "Đi trễ không phép",
    normalize_login_name("Về sớm không phép"): "Về sớm không phép",
    # Chấp nhận tên cũ/biến thể nếu danh mục đang dùng "Ra sớm không phép".
    normalize_login_name("Ra sớm không phép"): "Về sớm không phép",
}

# Các loại này tuyệt đối KHÔNG tham gia xếp hạng Người Thứ 1/2/3... dù tên danh mục
# sau này có bị chỉnh gần giống một nhóm phạt lũy tiến.
PROGRESSIVE_PENALTY_EXCLUDED_REASONS = {
    # Tên hiện tại trong LoaiNghi (STT 30-33).
    normalize_login_name("Ra ngoài vào muộn nhỏ hơn hoặc bằng 30 phút"),
    normalize_login_name("Ra ngoài vào muộn nhỏ hơn hoặc bằng 60 phút"),
    normalize_login_name("Ra ngoài vào muộn nhỏ hơn hoặc bằng 120 phút"),
    normalize_login_name("Ra ngoài vào muộn trên 120 phút"),
    # Tương thích tên lịch sử.
    normalize_login_name("Ra ngoài vào muộn dưới 30 phút"),
    normalize_login_name("Ra ngoài vào muộn dưới 60 phút"),
    normalize_login_name("Ra ngoài vào muộn dưới 120 phút"),
}

def get_progressive_penalty_reason(value):
    """Trả về tên chuẩn nếu loại nghỉ thuộc nhóm phạt lũy tiến, ngược lại trả về None."""
    key = normalize_login_name(str(value).replace("🔴", "").strip())
    if key in PROGRESSIVE_PENALTY_EXCLUDED_REASONS:
        return None
    return PROGRESSIVE_PENALTY_REASONS.get(key)

def is_progressive_penalty_reason(value):
    return get_progressive_penalty_reason(value) is not None

def is_nghi_khong_phep_reason(value):
    """Giữ tương thích với code cũ: chỉ kiểm tra riêng Nghỉ không phép."""
    return get_progressive_penalty_reason(value) == "Nghỉ không phép"

def _fallback_admin_remember_token():
    """Token bền vững cho tài khoản admin dự phòng; không lưu mật khẩu trong trình duyệt."""
    try:
        secret = str(st.secrets.get("vera_persistent_login_secret", "VERA-SPA-PERSISTENT-LOGIN-2026"))
    except Exception:
        secret = "VERA-SPA-PERSISTENT-LOGIN-2026"
    digest = hmac.new(secret.encode("utf-8"), b"fallback-admin", hashlib.sha256).hexdigest()
    return "vera_admin_" + digest

def _is_valid_fallback_admin_token(token):
    if not token:
        return False
    return hmac.compare_digest(str(token), _fallback_admin_remember_token())

