def _long_leave_request_type(row_or_value):
    """V92.6.82: bản ghi cũ không có Loại đơn được hiểu là Nghỉ dài hạn."""
    if isinstance(row_or_value, dict):
        value = row_or_value.get("Loại đơn", "")
    elif isinstance(row_or_value, pd.Series):
        value = row_or_value.get("Loại đơn", "")
    else:
        value = row_or_value
    value = str(value or "").strip()
    return value or LONG_LEAVE_REQUEST_TYPE_LONG


def _is_formal_long_leave_request(row_or_value):
    return normalize_login_name(_long_leave_request_type(row_or_value)) == normalize_login_name(
        LONG_LEAVE_REQUEST_TYPE_LONG
    )


def _is_annual_leave_request(row_or_value):
    return normalize_login_name(_long_leave_request_type(row_or_value)) == normalize_login_name(
        LONG_LEAVE_REQUEST_TYPE_ANNUAL
    )


def _leave_request_type_label_v92688(row_or_value):
    """Nhãn hiển thị chuẩn: không bao giờ để người dùng phải đoán loại đơn."""
    return (
        LONG_LEAVE_REQUEST_TYPE_ANNUAL
        if _is_annual_leave_request(row_or_value)
        else LONG_LEAVE_REQUEST_TYPE_LONG
    )


def _leave_request_title_v92688(row_or_value):
    return (
        "Đơn xin Nghỉ Phép năm"
        if _is_annual_leave_request(row_or_value)
        else "Đơn xin Nghỉ dài hạn"
    )


def _leave_request_period_label_v92688(row_or_value):
    return (
        "Thời gian Nghỉ Phép năm"
        if _is_annual_leave_request(row_or_value)
        else "Thời gian Nghỉ dài hạn"
    )


def _leave_request_content_label_v92688(row_or_value):
    return (
        "Nội dung / ghi chú Nghỉ Phép năm"
        if _is_annual_leave_request(row_or_value)
        else "Lý do Nghỉ dài hạn"
    )


def _leave_request_display_df_v92688(df):
    """Chuẩn hóa dataframe hiển thị mà không đổi schema legacy của NghiDaiHan."""
    if not isinstance(df, pd.DataFrame):
        return pd.DataFrame()
    out = df.copy()
    if out.empty:
        return out
    out["Loại đơn"] = out.apply(_leave_request_type_label_v92688, axis=1)
    if "Lý do nghỉ dài hạn" in out.columns:
        out["Nội dung đơn"] = out["Lý do nghỉ dài hạn"].astype(str)
    return out


def _filter_formal_long_leave_rows(df):
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame()
    if "Loại đơn" not in df.columns:
        return df.copy()
    return df[df.apply(_is_formal_long_leave_request, axis=1)].copy()


def _validate_and_write_annual_leave_request_to_main_data_v92682(
    employee_name, start_date, end_date, detail, approver, request_id=""
):
    """
    Duyệt đơn Phép năm -> ghi MainData theo lô, tối đa 7 ngày liên tiếp.
    Idempotent: nếu toàn bộ ngày đã có đúng `Nghỉ Phép năm` thì coi như đã ghi xong,
    giúp Admin có thể bấm lại nếu lần trước MainData thành công nhưng cập nhật trạng thái đơn bị gián đoạn.
    """
    try:
        if not isinstance(start_date, date) or not isinstance(end_date, date) or end_date < start_date:
            return False, "Khoảng ngày Phép năm không hợp lệ.", []
        count = (end_date - start_date).days + 1
        if count > 7:
            return False, "Đơn Phép năm chỉ được duyệt tối đa 7 ngày liên tiếp.", []

        client = get_gspread_client()
        if not client:
            return False, "Không kết nối được Google Sheets để đối chiếu MainData.", []
        sheet = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        live = _live_sheet_to_leave_df(sheet)
        live = combine_leave_sources_for_daily_stats(live)
        reason = "Nghỉ Phép năm"
        selected_dates = [start_date + timedelta(days=i) for i in range(count)]

        exact_existing = [
            d for d in selected_dates
            if _leave_exists_in_sources(live, d, employee_name, reason)
        ]
        if len(exact_existing) == len(selected_dates):
            return True, f"MainData đã có đủ {count} ngày Nghỉ Phép năm của đơn {request_id or ''}.".strip(), []
        if exact_existing:
            return False, (
                "MainData đang có một phần ngày của đơn Phép năm nhưng chưa đủ toàn bộ khoảng; "
                "hệ thống dừng để tránh ghi trùng/ghi một phần."
            ), []

        # Không cho tạo một dòng ngày nghỉ >0 thứ hai trong cùng ngày cho cùng nhân viên.
        # Đồng thời Phép năm phải tuân quota Có phép của từng ngày để tránh quá nhiều người nghỉ cùng lúc.
        for d in selected_dates:
            ok_day, msg_day = _validate_daily_employee_registration_rule(
                live, d, employee_name, reason, 1.0
            )
            if not ok_day:
                return False, f"{d.strftime('%d/%m/%Y')}: {msg_day}", []
            ok_quota, msg_quota = _validate_daily_group_quota(live, d, reason)
            if not ok_quota:
                return False, msg_quota, []

        # Kiểm tra quỹ Phép năm của chính nhân viên theo từng năm.
        try:
            creds = load_credentials_fresh()
        except Exception:
            creds = globals().get("df_credentials", pd.DataFrame())
        limit_pn = 0.0
        if isinstance(creds, pd.DataFrame) and not creds.empty and "Tên nhân viên" in creds.columns:
            hit = creds[
                creds["Tên nhân viên"].astype(str).apply(normalize_login_name)
                .eq(normalize_login_name(employee_name))
            ]
            if not hit.empty and "Phép năm" in hit.columns:
                v = pd.to_numeric(hit.iloc[-1].get("Phép năm", 0), errors="coerce")
                limit_pn = 0.0 if pd.isna(v) else float(v)

        hist = live.copy() if isinstance(live, pd.DataFrame) else pd.DataFrame()
        if not hist.empty and "Tên nhân viên" in hist.columns:
            hist = hist[
                hist["Tên nhân viên"].astype(str).apply(normalize_login_name)
                .eq(normalize_login_name(employee_name))
            ].copy()
            hist = _leave_rows_counting_toward_quota(hist)
        if not hist.empty:
            hist["__dt_ann_v92682"] = pd.to_datetime(hist.get("Ngày"), dayfirst=True, errors="coerce")
            hist["__days_ann_v92682"] = pd.to_numeric(hist.get("Số ngày tính", 0), errors="coerce").fillna(0.0)
        for yy in sorted({d.year for d in selected_dates}):
            required = float(sum(1 for d in selected_dates if d.year == yy))
            used = 0.0
            if not hist.empty and "Lý do nghỉ" in hist.columns:
                annual_mask = hist["Lý do nghỉ"].astype(str).apply(is_annual_leave_range_reason)
                year_mask = hist["__dt_ann_v92682"].dt.year.eq(yy)
                used = float(hist.loc[annual_mask & year_mask, "__days_ann_v92682"].sum())
            if limit_pn > 0 and used + required > limit_pn:
                return False, (
                    f"Vượt quỹ Phép năm {yy}: cần {required:g} ngày, đã dùng {used:g}, "
                    f"quỹ được cấp {limit_pn:g}."
                ), []

        detail_text = str(detail or "").strip()
        if request_id:
            prefix = f"Đơn Phép năm {request_id} đã duyệt"
            detail_text = f"{prefix} | {detail_text}" if detail_text else prefix
        return save_lich_nghi_range_to_backup_sheet(
            start_date, end_date, employee_name, reason, detail_text,
            1.0, 0.0, approver,
        )
    except Exception as e:
        return False, f"Lỗi ghi đơn Phép năm vào MainData: {e}", []


def long_leave_active_records(df=None):
    d = df.copy() if isinstance(df, pd.DataFrame) else load_long_leave_requests()
    if d.empty:
        return d
    d = _filter_formal_long_leave_rows(d)
    return d[d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)].copy()


def _annual_leave_request_periods_v92683(df=None):
    """Các khoảng đơn Phép năm dùng cho dashboard theo dõi của người duyệt."""
    d = df.copy() if isinstance(df, pd.DataFrame) else load_long_leave_requests()
    cols = ["Tên nhân viên", "Từ ngày", "Đến ngày", "Trạng thái", "ID", "Nguồn"]
    if not isinstance(d, pd.DataFrame) or d.empty:
        return pd.DataFrame(columns=cols)
    annual = d[d.apply(_is_annual_leave_request, axis=1)].copy()
    if annual.empty:
        return pd.DataFrame(columns=cols)
    annual["__start_v92683"] = annual["Từ ngày"].apply(_parse_vn_date)
    annual["__end_v92683"] = annual["Đến ngày"].apply(_parse_vn_date)
    annual = annual[annual["__start_v92683"].notna() & annual["__end_v92683"].notna()].copy()
    out = pd.DataFrame({
        "Tên nhân viên": annual["Tên nhân viên"].astype(str),
        "Từ ngày": annual["__start_v92683"].apply(lambda x: x.strftime("%d/%m/%Y")),
        "Đến ngày": annual["__end_v92683"].apply(lambda x: x.strftime("%d/%m/%Y")),
        "Trạng thái": annual["Trạng thái"].astype(str),
        "ID": (annual["ID"].astype(str) if "ID" in annual.columns else pd.Series("", index=annual.index, dtype=str)),
        "Nguồn": (annual["Nguồn"].astype(str) if "Nguồn" in annual.columns else pd.Series("", index=annual.index, dtype=str)),
    })
    out["__start_v92683"] = annual["__start_v92683"].values
    out["__end_v92683"] = annual["__end_v92683"].values
    return out.reset_index(drop=True)


def build_annual_leave_main_data_periods_v92683(start_date=None, end_date=None):
    """Gom các ngày Nghỉ Phép năm trong MainData thành khoảng liên tiếp theo nhân viên."""
    main = load_backup_sheet_data()
    if not isinstance(main, pd.DataFrame) or main.empty:
        return pd.DataFrame(columns=["Tên nhân viên", "Từ ngày", "Đến ngày", "Số ngày"])
    if not {"Ngày", "Tên nhân viên", "Lý do nghỉ"}.issubset(main.columns):
        return pd.DataFrame(columns=["Tên nhân viên", "Từ ngày", "Đến ngày", "Số ngày"])
    d = main[main["Lý do nghỉ"].astype(str).apply(is_annual_leave_range_reason)].copy()
    if d.empty:
        return pd.DataFrame(columns=["Tên nhân viên", "Từ ngày", "Đến ngày", "Số ngày"])
    d["__date_v92683"] = d["Ngày"].apply(_parse_vn_date)
    d = d[d["__date_v92683"].notna()].copy()
    if isinstance(start_date, date):
        d = d[d["__date_v92683"].apply(lambda x: x >= start_date)].copy()
    if isinstance(end_date, date):
        d = d[d["__date_v92683"].apply(lambda x: x <= end_date)].copy()
    if d.empty:
        return pd.DataFrame(columns=["Tên nhân viên", "Từ ngày", "Đến ngày", "Số ngày"])
    d["__emp_v92683"] = d["Tên nhân viên"].astype(str).apply(normalize_login_name)
    rows = []
    for _, g in d.groupby("__emp_v92683", sort=False):
        employee = str(g.iloc[0].get("Tên nhân viên", "") or "").strip()
        dates = sorted(set(g["__date_v92683"].tolist()))
        if not dates:
            continue
        seg_start = seg_prev = dates[0]
        for dd in dates[1:]:
            if dd == seg_prev + timedelta(days=1):
                seg_prev = dd
                continue
            rows.append({
                "Tên nhân viên": employee,
                "Từ ngày": seg_start.strftime("%d/%m/%Y"),
                "Đến ngày": seg_prev.strftime("%d/%m/%Y"),
                "Số ngày": (seg_prev - seg_start).days + 1,
                "__start_v92683": seg_start,
                "__end_v92683": seg_prev,
            })
            seg_start = seg_prev = dd
        rows.append({
            "Tên nhân viên": employee,
            "Từ ngày": seg_start.strftime("%d/%m/%Y"),
            "Đến ngày": seg_prev.strftime("%d/%m/%Y"),
            "Số ngày": (seg_prev - seg_start).days + 1,
            "__start_v92683": seg_start,
            "__end_v92683": seg_prev,
        })
    out = pd.DataFrame(rows)
    if out.empty:
        return pd.DataFrame(columns=["Tên nhân viên", "Từ ngày", "Đến ngày", "Số ngày"])
    return out.sort_values(["__start_v92683", "Tên nhân viên"], kind="stable").reset_index(drop=True)



# ==========================================================
# V92.6.89 - ĐIỀU KIỆN TẠO ĐƠN + KIỂM TRA TRÙNG TRƯỚC KHI DUYỆT
# ==========================================================
def _add_months_v92689(d, months):
    if not isinstance(d, date):
        return None
    total = d.year * 12 + (d.month - 1) + int(months)
    yy, mm0 = divmod(total, 12)
    mm = mm0 + 1
    dd = min(d.day, calendar.monthrange(yy, mm)[1])
    return date(yy, mm, dd)


def employee_start_work_date_v92689(employee_name, credentials_df=None):
    """Ngày bắt đầu làm: ưu tiên hồ sơ tài khoản cột U, fallback TichLuy cho dữ liệu cũ."""
    key = normalize_login_name(employee_name)
    if not key:
        return None
    try:
        creds = credentials_df if isinstance(credentials_df, pd.DataFrame) else load_credentials_recent()
        if isinstance(creds, pd.DataFrame) and not creds.empty and 'Tên nhân viên' in creds.columns:
            hit = creds[creds['Tên nhân viên'].astype(str).apply(normalize_login_name).eq(key)]
            if not hit.empty:
                d = _parse_vn_date(hit.iloc[-1].get('Ngày bắt đầu làm', ''))
                if d is not None:
                    return d
    except Exception:
        pass
    try:
        tl = load_tichluy_tracking()
        if isinstance(tl, pd.DataFrame) and not tl.empty and 'Tên nhân viên' in tl.columns:
            hit = tl[tl['Tên nhân viên'].astype(str).apply(normalize_login_name).eq(key)]
            if not hit.empty:
                return _parse_vn_date(hit.iloc[-1].get('Ngày bắt đầu làm', ''))
    except Exception:
        pass
    return None


def active_leave_request_for_employee_v92689(employee_name, requests_df=None, today=None):
    """Chỉ cho 1 đơn đang hoạt động tại một thời điểm, không phân biệt Phép năm/Nghỉ dài hạn."""
    d = requests_df.copy() if isinstance(requests_df, pd.DataFrame) else load_long_leave_requests()
    if not isinstance(d, pd.DataFrame) or d.empty:
        return None
    today = today if isinstance(today, date) else get_vn_today()
    key = normalize_login_name(employee_name)
    d = d[d['Tên nhân viên'].astype(str).apply(normalize_login_name).eq(key)].copy()
    if d.empty:
        return None
    active_statuses = {LONG_LEAVE_PENDING, LONG_LEAVE_APPROVED}
    d = d[d['Trạng thái'].astype(str).str.strip().isin(active_statuses)].copy()
    if d.empty:
        return None
    d['__end_gate_v92689'] = d['Đến ngày'].apply(_parse_vn_date)
    d = d[d['__end_gate_v92689'].apply(lambda x: x is None or x >= today)].copy()
    if d.empty:
        return None
    d['__start_gate_v92689'] = d['Từ ngày'].apply(_parse_vn_date)
    d = d.sort_values(['__start_gate_v92689', '__row'] if '__row' in d.columns else ['__start_gate_v92689'], ascending=False, kind='stable')
    return d.iloc[0].to_dict()


def employee_leave_request_gate_v92689(employee_name, requests_df=None, credentials_df=None, today=None):
    """Nhân viên phải đủ 3 tháng và không có đơn Phép năm/Nghỉ dài hạn đang hoạt động."""
    today = today if isinstance(today, date) else get_vn_today()
    start_work = employee_start_work_date_v92689(employee_name, credentials_df)
    if start_work is None:
        return False, "Hồ sơ chưa có Ngày bắt đầu làm. Vui lòng liên hệ Admin cập nhật trước khi tạo đơn.", None
    eligible_on = _add_months_v92689(start_work, 3)
    if eligible_on is None or today < eligible_on:
        return False, (
            f"Chưa đủ 3 tháng làm việc. Ngày bắt đầu làm: {start_work.strftime('%d/%m/%Y')} · "
            f"được tạo đơn từ {eligible_on.strftime('%d/%m/%Y') if eligible_on else ''}."
        ), start_work
    active = active_leave_request_for_employee_v92689(employee_name, requests_df, today)
    if active:
        return False, (
            f"Bạn đang có {_leave_request_type_label_v92688(active)} {active.get('ID','')} "
            f"({active.get('Từ ngày','')} → {active.get('Đến ngày','')}) ở trạng thái "
            f"{active.get('Trạng thái','')}. Mỗi lần chỉ được có 1 đơn Phép năm hoặc Nghỉ dài hạn đang hoạt động."
        ), start_work
    return True, f"Đủ điều kiện tạo đơn · Ngày bắt đầu làm {start_work.strftime('%d/%m/%Y')}", start_work


def leave_request_overlap_check_v92689(applicant, request_type, start_date, end_date, requests_df=None):
    """Đối chiếu người đã được duyệt trùng khoảng và mô phỏng tổng người nghỉ nếu duyệt đơn đang xét."""
    result = {
        'approved_long_unique': 0, 'approved_annual_unique': 0,
        'approved_total_unique': 0, 'after_long_unique': 0,
        'after_annual_unique': 0, 'after_total_unique': 0,
        'max_concurrent_after': 0, 'daily': pd.DataFrame(),
        'long_names': [], 'annual_names': [],
    }
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        return result
    if end_date < start_date:
        start_date, end_date = end_date, start_date

    reqs = requests_df.copy() if isinstance(requests_df, pd.DataFrame) else load_long_leave_requests()
    long_rows = _filter_formal_long_leave_rows(reqs)
    if isinstance(long_rows, pd.DataFrame) and not long_rows.empty:
        long_rows = long_rows[long_rows['Trạng thái'].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)].copy()
        long_rows['__s_v92689'] = long_rows['Từ ngày'].apply(_parse_vn_date)
        long_rows['__e_v92689'] = long_rows['Đến ngày'].apply(_parse_vn_date)
        long_rows = long_rows[
            long_rows['__s_v92689'].notna() & long_rows['__e_v92689'].notna()
            & long_rows['__s_v92689'].apply(lambda x: x <= end_date)
            & long_rows['__e_v92689'].apply(lambda x: x >= start_date)
        ].copy()
    else:
        long_rows = pd.DataFrame()

    annual = build_annual_leave_main_data_periods_v92683(start_date, end_date)
    if not isinstance(annual, pd.DataFrame):
        annual = pd.DataFrame()

    applicant_key = normalize_login_name(applicant)
    long_names = set()
    if not long_rows.empty:
        long_names = {
            normalize_login_name(x) for x in long_rows['Tên nhân viên'].astype(str).tolist()
            if normalize_login_name(x) and normalize_login_name(x) != applicant_key
        }
    annual_names = set()
    if not annual.empty:
        annual_names = {
            normalize_login_name(x) for x in annual['Tên nhân viên'].astype(str).tolist()
            if normalize_login_name(x) and normalize_login_name(x) != applicant_key
        }

    display_long = sort_employee_names(
        [str(x) for x in (long_rows['Tên nhân viên'].astype(str).tolist() if not long_rows.empty else [])
         if normalize_login_name(x) != applicant_key], include_inactive=True
    )
    display_annual = sort_employee_names(
        [str(x) for x in (annual['Tên nhân viên'].astype(str).tolist() if not annual.empty else [])
         if normalize_login_name(x) != applicant_key], include_inactive=True
    )
    result['long_names'] = list(dict.fromkeys(display_long))
    result['annual_names'] = list(dict.fromkeys(display_annual))
    result['approved_long_unique'] = len(long_names)
    result['approved_annual_unique'] = len(annual_names)
    result['approved_total_unique'] = len(long_names | annual_names)

    is_annual = normalize_login_name(request_type) == normalize_login_name(LONG_LEAVE_REQUEST_TYPE_ANNUAL)
    after_long = set(long_names)
    after_annual = set(annual_names)
    if applicant_key:
        (after_annual if is_annual else after_long).add(applicant_key)
    result['after_long_unique'] = len(after_long)
    result['after_annual_unique'] = len(after_annual)
    result['after_total_unique'] = len(after_long | after_annual)

    rows = []
    curr = start_date
    while curr <= end_date:
        day_long_names = []
        if not long_rows.empty:
            dd = long_rows[
                long_rows['__s_v92689'].apply(lambda x: x <= curr)
                & long_rows['__e_v92689'].apply(lambda x: x >= curr)
            ]
            day_long_names = [
                str(x).strip() for x in dd['Tên nhân viên'].astype(str).tolist()
                if normalize_login_name(x) != applicant_key
            ]
        day_ann_names = []
        if not annual.empty:
            aa = annual[
                annual['__start_v92683'].apply(lambda x: x <= curr)
                & annual['__end_v92683'].apply(lambda x: x >= curr)
            ]
            day_ann_names = [
                str(x).strip() for x in aa['Tên nhân viên'].astype(str).tolist()
                if normalize_login_name(x) != applicant_key
            ]
        long_count = len({normalize_login_name(x) for x in day_long_names if normalize_login_name(x)})
        ann_count = len({normalize_login_name(x) for x in day_ann_names if normalize_login_name(x)})
        after_long_count = long_count + (0 if is_annual else 1)
        after_ann_count = ann_count + (1 if is_annual else 0)
        after_total = after_long_count + after_ann_count
        result['max_concurrent_after'] = max(result['max_concurrent_after'], after_total)
        rows.append({
            'Ngày': curr.strftime('%d/%m/%Y'),
            'Nghỉ dài hạn đã duyệt': long_count,
            'Phép năm đã duyệt': ann_count,
            'Tổng đã duyệt': long_count + ann_count,
            'Nếu duyệt · Nghỉ dài hạn': after_long_count,
            'Nếu duyệt · Phép năm': after_ann_count,
            'Nếu duyệt · Tổng người nghỉ': after_total,
            'NV nghỉ dài hạn': ', '.join(sort_employee_names(day_long_names, include_inactive=True)),
            'NV Phép năm': ', '.join(sort_employee_names(day_ann_names, include_inactive=True)),
            'Nếu duyệt · NV nghỉ dài hạn': ', '.join(sort_employee_names(
                day_long_names + ([] if is_annual else [str(applicant).strip()]), include_inactive=True
            )),
            'Nếu duyệt · NV Phép năm': ', '.join(sort_employee_names(
                day_ann_names + ([str(applicant).strip()] if is_annual else []), include_inactive=True
            )),
        })
        curr += timedelta(days=1)
    result['daily'] = pd.DataFrame(rows)
    return result


def reset_widget_keys_v92689(*keys):
    """Reset widget về mặc định ở lượt render kế tiếp; không đụng state ghim/show-hide."""
    for key in keys:
        try:
            st.session_state.pop(str(key), None)
        except Exception:
            pass

def reset_widget_prefixes_v92689(*prefixes):
    """Reset nhóm widget theo prefix; giữ nguyên state ghim và state show/hide do user quyết định."""
    pref = tuple(str(x) for x in prefixes if str(x))
    if not pref:
        return
    protected = ("vera_sidebar_pin", "vera_expander", "_vera_expander", "pin_")
    for key in list(st.session_state.keys()):
        skey = str(key)
        if skey.startswith(protected):
            continue
        if skey.startswith(pref):
            try:
                st.session_state.pop(key, None)
            except Exception:
                pass

def _leave_day_unit_v92689(row):
    try:
        v = pd.to_numeric(row.get('Số ngày tính', 0), errors='coerce')
        if not pd.isna(v) and float(v) > 0:
            return float(v)
    except Exception:
        pass
    reason = normalize_login_name(row.get('Lý do nghỉ', ''))
    if not reason:
        return 0.0
    # Dòng nghỉ cả ngày KHÔNG phép thường có G=0 nhưng vẫn phải tính 1 ngày trong thống kê cá nhân.
    if 'nghi' in reason and 'di tre' not in reason and 've som' not in reason and 'ra ngoai' not in reason:
        return 1.0
    if any(x in reason for x in ('di tre', 've som')):
        return 0.5
    return 0.0


def leave_manage_summary_v92689(df):
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {'total': 0.0, 'paid': 0.0, 'arising': 0.0, 'unpaid': 0.0}
    paid = arising = unpaid = 0.0
    for _, row in df.iterrows():
        unit = _leave_day_unit_v92689(row)
        leave_type = normalize_login_name(_leave_type_for_reason(row.get('Lý do nghỉ', '')))
        reason = normalize_login_name(row.get('Lý do nghỉ', ''))
        if leave_type == normalize_login_name('Có phép') or 'phep nam' in reason:
            paid += unit
        elif leave_type == normalize_login_name('Phát sinh') or 'phat sinh' in reason:
            arising += unit
        elif leave_type == normalize_login_name('Không phép') or 'khong phep' in reason:
            unpaid += unit
    return {'total': paid + arising + unpaid, 'paid': paid, 'arising': arising, 'unpaid': unpaid}


def leave_manage_excel_bytes_v92689(df):
    from openpyxl.styles import Font, Alignment
    out = io.BytesIO()
    export_df = _excel_safe_dataframe(df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame())
    with pd.ExcelWriter(out, engine='openpyxl') as writer:
        export_df.to_excel(writer, index=False, sheet_name='QuanLyLichNghi')
        ws = writer.book['QuanLyLichNghi']
        ws.freeze_panes = 'A2'
        ws.auto_filter.ref = ws.dimensions
        for cell in ws[1]:
            cell.font = Font(bold=True)
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        for col_cells in ws.columns:
            max_len = max([len(str(c.value or '')) for c in col_cells[:100]] + [10])
            ws.column_dimensions[col_cells[0].column_letter].width = min(max(max_len + 2, 12), 42)
    return out.getvalue()


def build_annual_leave_daily_capacity_v92683(start_date, end_date):
    """
    Bảng năng lực nghỉ theo từng ngày để Admin/Quản lý/Leader/Lễ tân nhìn trước khi duyệt Phép năm.
    Hạn mức dùng đúng quota Có phép hiện tại; đơn Chờ duyệt chỉ hiển thị tham khảo, chưa chiếm quota.
    """
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        return pd.DataFrame()
    if end_date < start_date:
        start_date, end_date = end_date, start_date
    # Giới hạn hiển thị 366 ngày để tránh dashboard vô tình tạo bảng quá lớn.
    if (end_date - start_date).days > 365:
        end_date = start_date + timedelta(days=365)

    main = load_backup_sheet_data()
    main = combine_leave_sources_for_daily_stats(main)
    quota_main = _leave_rows_counting_toward_quota(main)
    if isinstance(quota_main, pd.DataFrame) and not quota_main.empty:
        quota_main = quota_main.copy()
        quota_main["__date_v92683"] = quota_main["Ngày"].apply(_parse_vn_date)
        quota_main["__days_v92683"] = pd.to_numeric(
            quota_main.get("Số ngày tính", 0), errors="coerce"
        ).fillna(0.0)
        reason_map = _leave_reason_type_map(globals().get("df_loai_nghi", pd.DataFrame()))
        quota_main["__group_v92683"] = quota_main["Lý do nghỉ"].apply(
            lambda x: _daily_leave_group(x, reason_map)
        )
    else:
        quota_main = pd.DataFrame()

    periods = _annual_leave_request_periods_v92683()
    pending = periods[
        periods["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_PENDING)
    ].copy() if not periods.empty else pd.DataFrame()

    rows = []
    curr = start_date
    while curr <= end_date:
        limits = _daily_leave_quota_limits(curr)
        co_names = []
        annual_names = []
        if isinstance(quota_main, pd.DataFrame) and not quota_main.empty:
            dd = quota_main[
                quota_main["__date_v92683"].eq(curr)
                & quota_main["__group_v92683"].eq("co_phep")
                & quota_main["__days_v92683"].gt(0)
            ].copy()
            co_names = sort_employee_names(
                dd.get("Tên nhân viên", pd.Series(dtype=str)).dropna().astype(str).tolist(),
                include_inactive=True,
            )
            ann = dd[dd["Lý do nghỉ"].astype(str).apply(is_annual_leave_range_reason)]
            annual_names = sort_employee_names(
                ann.get("Tên nhân viên", pd.Series(dtype=str)).dropna().astype(str).tolist(),
                include_inactive=True,
            )

        pending_names = []
        if isinstance(pending, pd.DataFrame) and not pending.empty:
            pmask = pending.apply(
                lambda r: r.get("__start_v92683") <= curr <= r.get("__end_v92683"), axis=1
            )
            pending_names = sort_employee_names(
                pending.loc[pmask, "Tên nhân viên"].dropna().astype(str).tolist(),
                include_inactive=True,
            )

        used = len({normalize_login_name(x) for x in co_names if str(x).strip()})
        limit = int(limits.get("co_phep", 0) or 0)
        rows.append({
            "Ngày": curr.strftime("%d/%m/%Y"),
            "Thứ": _vn_weekday_label(curr),
            "Có phép hiện có": used,
            "Hạn mức Có phép": limit,
            "Còn chỗ": max(0, limit - used),
            "Đang ghi Phép năm": ", ".join(annual_names),
            "Tất cả Có phép": ", ".join(co_names),
            "Phép năm chờ duyệt": ", ".join(pending_names),
            "Số đơn chờ": len(pending_names),
        })
        curr += timedelta(days=1)
    return pd.DataFrame(rows)


def annual_leave_overlap_summary_v92683(start_date, end_date):
    daily = build_annual_leave_daily_capacity_v92683(start_date, end_date)
    if not isinstance(daily, pd.DataFrame) or daily.empty:
        return {"daily": pd.DataFrame(), "max_used": 0, "min_remaining": 0, "full_days": 0}
    used = pd.to_numeric(daily["Có phép hiện có"], errors="coerce").fillna(0)
    remaining = pd.to_numeric(daily["Còn chỗ"], errors="coerce").fillna(0)
    return {
        "daily": daily,
        "max_used": int(used.max()) if len(used) else 0,
        "min_remaining": int(remaining.min()) if len(remaining) else 0,
        "full_days": int((remaining <= 0).sum()),
    }


def pending_long_leave_count():
    d = load_long_leave_requests()
    if d.empty:
        return 0
    return int(
        d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_PENDING).sum()
    )


LONG_LEAVE_REQUEST_PAUSE_KEY = "long_leave_request_pause_v905"


@st.cache_data(ttl=15, show_spinner=False)
def load_long_leave_request_pause():
    default = {
        "enabled": False,
        "message": "Admin đang tạm dừng nhận đơn Nghỉ dài hạn và Nghỉ Phép năm.",
        "updated_by": "",
        "updated_at": "",
    }
    try:
        ws, err = _ensure_ui_theme_storage()
        if err or ws is None:
            return default.copy()
        vals = _gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if row and str(row[0]).strip() == LONG_LEAVE_REQUEST_PAUSE_KEY:
                try:
                    raw = json.loads(row[1]) if len(row) > 1 and str(row[1]).strip() else {}
                except Exception:
                    raw = {}
                out = default.copy()
                if isinstance(raw, dict):
                    out["enabled"] = bool(raw.get("enabled", False))
                    out["message"] = str(raw.get("message", default["message"]) or default["message"]).strip()
                    out["updated_by"] = str(raw.get("updated_by", "") or "").strip()
                    out["updated_at"] = str(raw.get("updated_at", "") or "").strip()
                return out
        return default.copy()
    except Exception:
        return default.copy()


def save_long_leave_request_pause(enabled, username, message=""):
    try:
        ws, err = _ensure_ui_theme_storage()
        if err or ws is None:
            return False, err or "Không mở được sheet cấu hình."
        vals = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(vals[1:], start=2):
            if row and str(row[0]).strip() == LONG_LEAVE_REQUEST_PAUSE_KEY:
                row_idx = idx
                break
        now = datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")
        payload = {
            "enabled": bool(enabled),
            "message": str(message or "Admin đang tạm dừng nhận đơn Nghỉ dài hạn và Nghỉ Phép năm.").strip(),
            "updated_by": str(username or "").strip(),
            "updated_at": now,
        }
        row = [
            LONG_LEAVE_REQUEST_PAUSE_KEY,
            json.dumps(payload, ensure_ascii=False),
            now,
            str(username or "").strip(),
        ]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:D{row_idx}", [row])
        else:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        try:
            load_long_leave_request_pause.clear()
        except Exception:
            pass
        return True, "Đã cập nhật trạng thái nhận đơn Nghỉ dài hạn và Nghỉ Phép năm."
    except Exception as e:
        return False, f"Lỗi cập nhật trạng thái nhận đơn: {e}"


def count_employee_long_leave_requests_in_month(employee_name, ref_date=None):
    """Đếm số đơn do chính nhân viên gửi trong tháng của Ngày gửi."""
    ref_date = ref_date or get_vn_today()
    d = load_long_leave_requests()
    if not isinstance(d, pd.DataFrame) or d.empty:
        return 0
    emp_key = normalize_login_name(employee_name)
    work = d[
        d["Tên nhân viên"].astype(str).apply(normalize_login_name).eq(emp_key)
    ].copy()
    work = _filter_formal_long_leave_rows(work)
    if "Nguồn" in work.columns:
        work = work[
            work["Nguồn"].astype(str).str.contains("Nhân viên gửi yêu cầu", case=False, na=False)
        ]
    if work.empty:
        return 0
    parsed = work["Ngày gửi"].apply(_parse_vn_date)
    return int(sum(
        1 for dt in parsed
        if dt is not None and dt.year == ref_date.year and dt.month == ref_date.month
    ))


def _long_leave_rejected_for_notifications(limit=5):
    d = load_long_leave_requests()
    if not isinstance(d, pd.DataFrame) or d.empty:
        return pd.DataFrame()
    out = d[d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_REJECTED)].copy()
    if "__row" in out.columns:
        out = out.sort_values("__row", ascending=False)
    return out.head(max(1, int(limit)))


def reconcile_long_leave_employment_statuses():
    """
    Đồng bộ trạng thái làm việc theo ngày thực tế:
    - Đã duyệt và hôm nay nằm trong khoảng nghỉ -> Tạm thời nghỉ việc.
    - Đã duyệt và đã qua ngày kết thúc -> Đang làm việc + chuyển đơn thành Đã kết thúc.
    Chạy khi app có lượt thực thi, không cần người dùng thao tác tại trang này.
    """
    try:
        d = load_long_leave_requests()
        if not isinstance(d, pd.DataFrame) or d.empty:
            return
        today = get_vn_today()

        # Đơn Phép năm dùng cùng vòng đời duyệt nhưng tuyệt đối không đổi trạng thái làm việc.
        # Sau khi qua ngày kết thúc chỉ chuyển trạng thái đơn sang Đã kết thúc.
        approved_all_v92682 = d[
            d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)
        ].copy()
        if not approved_all_v92682.empty:
            annual_approved_v92682 = approved_all_v92682[
                approved_all_v92682.apply(_is_annual_leave_request, axis=1)
            ].copy()
            for _, _ann_row_v92682 in annual_approved_v92682.iterrows():
                _ann_end_v92682 = _parse_vn_date(_ann_row_v92682.get("Đến ngày", ""))
                if _ann_end_v92682 is not None and today > _ann_end_v92682:
                    try:
                        update_long_leave_row(
                            int(_ann_row_v92682.get("__row", 0)),
                            {"Trạng thái": LONG_LEAVE_ENDED},
                            "SYSTEM",
                        )
                    except Exception:
                        pass

        approved = _filter_formal_long_leave_rows(d)
        approved = approved[approved["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)].copy()
        if approved.empty:
            return

        creds = load_credentials_recent()
        if not isinstance(creds, pd.DataFrame):
            creds = pd.DataFrame()

        for _, row in approved.iterrows():
            start_d = _parse_vn_date(row.get("Từ ngày", ""))
            end_d = _parse_vn_date(row.get("Đến ngày", ""))
            emp = str(row.get("Tên nhân viên", "")).strip()
            if not emp or start_d is None or end_d is None:
                continue

            current_status = ""
            if not creds.empty and "Tên nhân viên" in creds.columns:
                hit = creds[
                    creds["Tên nhân viên"].astype(str).apply(normalize_login_name)
                    .eq(normalize_login_name(emp))
                ]
                if not hit.empty:
                    current_status = str(hit.iloc[-1].get("Trạng thái làm việc", "")).strip()

            if start_d <= today <= end_d:
                # Đã nghỉ việc là trạng thái cuối cùng; nghỉ dài hạn không được bật lại Tạm nghỉ.
                if current_status != EMPLOYMENT_STATUS_LEFT and current_status != EMPLOYMENT_STATUS_TEMP:
                    set_employee_employment_status(emp, EMPLOYMENT_STATUS_TEMP, "SYSTEM")
            elif today > end_d:
                # Chỉ đưa về Đang làm việc nếu đúng là đang Tạm nghỉ; tuyệt đối không hồi sinh người Đã nghỉ việc.
                if current_status == EMPLOYMENT_STATUS_TEMP:
                    set_employee_employment_status(emp, EMPLOYMENT_STATUS_ACTIVE, "SYSTEM")
                try:
                    update_long_leave_row(
                        int(row.get("__row", 0)),
                        {"Trạng thái": LONG_LEAVE_ENDED},
                        "SYSTEM",
                    )
                except Exception:
                    pass
    except Exception:
        pass


def _staff_plan_last_col():
    return re.sub(r"\d", "", gspread.utils.rowcol_to_a1(1, len(STAFF_PLAN_HEADERS)))


def _get_staff_plan_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_MAT_KHAU_ID)
    ws = _get_or_create_worksheet(
        ss, STAFF_PLAN_WORKSHEET, rows=3000, cols=len(STAFF_PLAN_HEADERS)
    )
    if int(getattr(ws, "col_count", 0) or 0) < len(STAFF_PLAN_HEADERS):
        _gs_call_with_backoff(ws.resize, cols=len(STAFF_PLAN_HEADERS))
    header = _gs_call_with_backoff(ws.row_values, 1)
    if header[:len(STAFF_PLAN_HEADERS)] != STAFF_PLAN_HEADERS:
        gspread_update_range(
            ws, f"A1:{_staff_plan_last_col()}1", [STAFF_PLAN_HEADERS]
        )
    return ws


@st.cache_data(ttl=60, show_spinner=False)
def load_staff_schedule_plans():
    try:
        ws = _get_staff_plan_worksheet()
        if ws is None:
            return pd.DataFrame(columns=STAFF_PLAN_HEADERS + ["__row"])
        vals = _gs_call_with_backoff(ws.get_all_values)
        rows = []
        for ridx, row in enumerate(vals[1:], start=2):
            rr = list(row[:len(STAFF_PLAN_HEADERS)]) + [""] * max(
                0, len(STAFF_PLAN_HEADERS) - len(row)
            )
            if any(str(v).strip() for v in rr):
                rec = dict(zip(STAFF_PLAN_HEADERS, rr[:len(STAFF_PLAN_HEADERS)]))
                rec["__row"] = ridx
                rows.append(rec)
        return pd.DataFrame(rows) if rows else pd.DataFrame(
            columns=STAFF_PLAN_HEADERS + ["__row"]
        )
    except Exception:
        return pd.DataFrame(columns=STAFF_PLAN_HEADERS + ["__row"])


def _clear_staff_plan_cache():
    try:
        load_staff_schedule_plans.clear()
    except Exception:
        pass


def _staff_plan_id(employee_name, plan_type):
    now = datetime.now(VN_TZ)
    base = (
        f"{normalize_login_name(employee_name)}|{normalize_login_name(plan_type)}|"
        f"{now.isoformat()}|{secrets.token_hex(3)}"
    )
    return "PLAN-" + hashlib.sha1(base.encode("utf-8")).hexdigest()[:14].upper()


def append_staff_schedule_plan(
    employee_name, plan_type, start_date, end_date=None, shift_name="",
    cycle="", note="", created_by="",
):
    """Lưu một kế hoạch nhân sự. Ngày quay lại làm = `Đến ngày` của Nghỉ dài hạn."""
    try:
        employee_name = str(employee_name or "").strip()
        plan_type = str(plan_type or "").strip()
        if not employee_name:
            return False, "Vui lòng chọn nhân viên.", ""
        if plan_type not in {STAFF_PLAN_SHIFT, STAFF_PLAN_LONG_LEAVE, STAFF_PLAN_RESIGN}:
            return False, "Loại kế hoạch không hợp lệ.", ""
        if not isinstance(start_date, date):
            return False, "Ngày bắt đầu không hợp lệ.", ""
        if plan_type == STAFF_PLAN_SHIFT and not str(shift_name or "").strip():
            return False, "Vui lòng chọn ca sẽ áp dụng.", ""
        if plan_type == STAFF_PLAN_LONG_LEAVE:
            if not isinstance(end_date, date):
                return False, "Vui lòng chọn ngày bắt đầu quay lại làm việc.", ""
            if end_date <= start_date:
                return False, "Ngày quay lại làm việc phải sau ngày bắt đầu nghỉ dài hạn.", ""

        # Chống trùng kế hoạch đang còn hiệu lực.
        existing = load_staff_schedule_plans()
        if isinstance(existing, pd.DataFrame) and not existing.empty:
            d = existing.copy()
            d = d[
                d["Tên nhân viên"].astype(str).apply(normalize_login_name)
                .eq(normalize_login_name(employee_name))
            ]
            d = d[~d["Trạng thái"].astype(str).str.strip().eq(STAFF_PLAN_CANCELLED)]
            d = d[d["Loại kế hoạch"].astype(str).str.strip().eq(plan_type)]
            if plan_type == STAFF_PLAN_SHIFT:
                for _, r in d.iterrows():
                    if _parse_vn_date(r.get("Từ ngày", "")) == start_date:
                        return False, (
                            f"{employee_name} đã có kế hoạch đổi ca vào "
                            f"{start_date.strftime('%d/%m/%Y')}. Hãy hủy kế hoạch cũ trước."
                        ), ""
            elif plan_type == STAFF_PLAN_LONG_LEAVE:
                for _, r in d.iterrows():
                    rs = _parse_vn_date(r.get("Từ ngày", ""))
                    retd = _parse_vn_date(r.get("Đến ngày", ""))
                    if rs is None or retd is None:
                        continue
                    # Khoảng nghỉ được hiểu [Từ ngày, Ngày quay lại).
                    if start_date < retd and end_date > rs:
                        return False, (
                            f"{employee_name} đã có kế hoạch nghỉ dài hạn chồng lấn "
                            f"{rs.strftime('%d/%m/%Y')} → {retd.strftime('%d/%m/%Y')}."
                        ), ""
            elif plan_type == STAFF_PLAN_RESIGN:
                # Chỉ cho một kế hoạch Nghỉ việc chưa hủy/chưa hoàn tất cho mỗi nhân viên.
                pending_resign = d[
                    ~d["Trạng thái"].astype(str).str.strip()
                    .isin([STAFF_PLAN_DONE, STAFF_PLAN_CANCELLED])
                ]
                if not pending_resign.empty:
                    rr = pending_resign.iloc[-1]
                    rd = _parse_vn_date(rr.get("Từ ngày", ""))
                    return False, (
                        f"{employee_name} đã có kế hoạch Nghỉ việc"
                        + (f" từ {rd.strftime('%d/%m/%Y')}" if isinstance(rd, date) else "")
                        + ". Hãy hủy kế hoạch cũ trước."
                    ), ""

        ws = _get_staff_plan_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets để lưu kế hoạch.", ""
        now = datetime.now(VN_TZ)
        plan_id = _staff_plan_id(employee_name, plan_type)
        row = [
            plan_id, employee_name, plan_type, start_date.strftime("%d/%m/%Y"),
            end_date.strftime("%d/%m/%Y") if isinstance(end_date, date) else "",
            str(shift_name or "").strip(), str(cycle or "").strip(),
            str(note or "").strip(), STAFF_PLAN_PENDING,
            now.strftime("%d/%m/%Y"), now.strftime("%H:%M:%S"),
            str(created_by or "").strip(), "", "", "",
        ]
        _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        _clear_staff_plan_cache()
        return True, "Đã lưu kế hoạch/hẹn ngày nhân sự.", plan_id
    except Exception as e:
        return False, f"Lỗi lưu kế hoạch nhân sự: {e}", ""


def update_staff_schedule_plan_row(row_idx, updates):
    try:
        row_idx = int(row_idx)
        ws = _get_staff_plan_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets."
        raw = _gs_call_with_backoff(
            ws.get, f"A{row_idx}:{_staff_plan_last_col()}{row_idx}"
        )
        current = list(raw[0]) if raw and raw[0] else []
        current += [""] * max(0, len(STAFF_PLAN_HEADERS) - len(current))
        rec = dict(zip(STAFF_PLAN_HEADERS, current[:len(STAFF_PLAN_HEADERS)]))
        for k, v in dict(updates or {}).items():
            if k in rec:
                rec[k] = v
        out = [rec.get(h, "") for h in STAFF_PLAN_HEADERS]
        gspread_update_range(
            ws, f"A{row_idx}:{_staff_plan_last_col()}{row_idx}", [out],
            value_input_option="USER_ENTERED",
        )
        _clear_staff_plan_cache()
        return True, "Đã cập nhật kế hoạch."
    except Exception as e:
        return False, f"Lỗi cập nhật kế hoạch: {e}"


def cancel_staff_schedule_plan(row_idx, actor):
    now = datetime.now(VN_TZ)
    return update_staff_schedule_plan_row(
        row_idx,
        {
            "Trạng thái": STAFF_PLAN_CANCELLED,
            "Ngày áp dụng": now.strftime("%d/%m/%Y"),
            "Giờ áp dụng": now.strftime("%H:%M:%S"),
            "Kết quả": f"Đã hủy bởi {actor}",
        },
    )


def _apply_employee_shift_plan(employee_name, shift_name, effective_date, cycle=""):
    """Áp dụng đúng O:P:Q cho một nhân viên khi kế hoạch tới hạn."""
    try:
        employee_name = str(employee_name or "").strip()
        shift_name = str(shift_name or "").strip()
        if not employee_name or not shift_name:
            return False, "Thiếu nhân viên hoặc ca áp dụng."

        creds = load_credentials_recent()
        role = ""
        if isinstance(creds, pd.DataFrame) and not creds.empty:
            hit = creds[
                creds["Tên nhân viên"].astype(str).apply(normalize_login_name)
                .eq(normalize_login_name(employee_name))
            ]
            if not hit.empty:
                role = str(hit.iloc[-1].get("Phân quyền", "") or "").strip().lower()
        if not role:
            return False, f"Không tìm thấy hồ sơ của {employee_name}."
        dep = _shift_department_label(role)
        valid_shifts = list(get_shift_options(dep))
        if shift_name not in valid_shifts:
            return False, f"Ca '{shift_name}' không thuộc danh mục hiện tại của bộ phận {dep}."
        if cycle and cycle not in SHIFT_CYCLE_OPTIONS:
            return False, f"Chu kỳ '{cycle}' không hợp lệ."

        client = get_gspread_client()
        if not client:
            return False, "Không kết nối được Google Sheets."
        sheet = client.open_by_key(SHEET_MAT_KHAU_ID).get_worksheet(0)
        vals = _gs_call_with_backoff(sheet.get_all_values)
        target_row = None
        for ridx, row in enumerate(vals[1:], start=2):
            if len(row) > 1 and normalize_login_name(row[1]) == normalize_login_name(employee_name):
                target_row = ridx
                break
        if target_row is None:
            return False, f"Không tìm thấy dòng tài khoản của {employee_name}."
        gspread_update_range(
            sheet, f"O{target_row}:Q{target_row}",
            [[shift_name, effective_date.strftime("%d/%m/%Y"), str(cycle or "").strip()]],
            value_input_option="USER_ENTERED",
        )
        _clear_dynamic_data_caches()
        try:
            load_credentials.clear()
            load_credentials_recent.clear()
        except Exception:
            pass
        return True, (
            f"Đã chuyển {employee_name} sang {shift_name} từ "
            f"{effective_date.strftime('%d/%m/%Y')}."
        )
    except Exception as e:
        return False, f"Lỗi áp dụng ca: {e}"


def _finish_formal_long_leave_on_planned_return(employee_name, return_date):
    """Nếu có đơn nghỉ dài hạn đã duyệt chồng tới ngày quay lại, kết thúc đơn để tránh trạng thái bị bật lại."""
    try:
        d = load_long_leave_requests()
        if not isinstance(d, pd.DataFrame) or d.empty:
            return 0
        d = _filter_formal_long_leave_rows(d)
        matched = d[
            d["Tên nhân viên"].astype(str).apply(normalize_login_name)
            .eq(normalize_login_name(employee_name))
            & d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)
        ]
        changed = 0
        for _, row in matched.iterrows():
            sd = _parse_vn_date(row.get("Từ ngày", ""))
            ed = _parse_vn_date(row.get("Đến ngày", ""))
            if sd is None or ed is None:
                continue
            if sd <= return_date <= ed:
                ok, _ = update_long_leave_row(
                    int(row.get("__row", 0)),
                    {"Trạng thái": LONG_LEAVE_ENDED, "Đến ngày": return_date.strftime("%d/%m/%Y")},
                    "SYSTEM - LỊCH HẸN NHÂN SỰ",
                )
                if ok:
                    changed += 1
        return changed
    except Exception:
        return 0


def reconcile_staff_schedule_plans():
    """
    V92.6.81 - Tự áp dụng kế hoạch theo NGÀY khi app/Scheduler có lượt chạy.

    - Đổi ca: đến ngày hiệu lực -> cập nhật Ca làm việc + Ngày bắt đầu ca + Chu kỳ.
    - Nghỉ dài hạn: từ ngày bắt đầu đến trước ngày quay lại -> Tạm thời nghỉ việc.
      Từ ngày quay lại -> Đang làm việc và kế hoạch hoàn tất.
    - Nghỉ việc: tới ngày hiệu lực -> chuyển trạng thái thành Đã nghỉ việc và hoàn tất kế hoạch.
    """
    try:
        plans = load_staff_schedule_plans()
        if not isinstance(plans, pd.DataFrame) or plans.empty:
            return {"applied": 0, "errors": 0}
        today = get_vn_today()
        now = datetime.now(VN_TZ)
        result = {"applied": 0, "errors": 0}
        status_map = load_employment_status_map()

        # Theo ngày rồi theo dòng để nhiều kế hoạch đổi ca tới hạn được áp dụng đúng thứ tự.
        work = plans.copy()
        work["__start"] = work["Từ ngày"].apply(_parse_vn_date)
        work = work.sort_values(["__start", "__row"], kind="stable", na_position="last")

        for _, row in work.iterrows():
            state = str(row.get("Trạng thái", "") or "").strip()
            if state == STAFF_PLAN_CANCELLED:
                continue
            plan_type = str(row.get("Loại kế hoạch", "") or "").strip()
            employee = str(row.get("Tên nhân viên", "") or "").strip()
            start_d = _parse_vn_date(row.get("Từ ngày", ""))
            end_d = _parse_vn_date(row.get("Đến ngày", ""))
            row_idx = int(row.get("__row", 0) or 0)
            if not employee or start_d is None or row_idx <= 1:
                continue

            if plan_type == STAFF_PLAN_SHIFT:
                if today < start_d or state == STAFF_PLAN_DONE:
                    continue
                ok, msg = _apply_employee_shift_plan(
                    employee, row.get("Ca áp dụng", ""), start_d, row.get("Chu kỳ", "")
                )
                update_staff_schedule_plan_row(
                    row_idx,
                    {
                        "Trạng thái": STAFF_PLAN_DONE if ok else STAFF_PLAN_ERROR,
                        "Ngày áp dụng": now.strftime("%d/%m/%Y"),
                        "Giờ áp dụng": now.strftime("%H:%M:%S"),
                        "Kết quả": msg,
                    },
                )
                result["applied" if ok else "errors"] += 1
                continue

            if plan_type == STAFF_PLAN_RESIGN:
                if today < start_d or state == STAFF_PLAN_DONE:
                    continue
                emp_key = normalize_login_name(employee)
                current_status = status_map.get(emp_key, EMPLOYMENT_STATUS_ACTIVE)
                changed_status = current_status != EMPLOYMENT_STATUS_LEFT
                ok = True
                msg = f"{employee} đến ngày nghỉ việc."
                if changed_status:
                    ok, msg = set_employee_employment_status(
                        employee, EMPLOYMENT_STATUS_LEFT, "SYSTEM - LỊCH HẸN NHÂN SỰ"
                    )
                    if ok:
                        status_map[emp_key] = EMPLOYMENT_STATUS_LEFT
                update_staff_schedule_plan_row(
                    row_idx,
                    {
                        "Trạng thái": STAFF_PLAN_DONE if ok else STAFF_PLAN_ERROR,
                        "Ngày áp dụng": now.strftime("%d/%m/%Y"),
                        "Giờ áp dụng": now.strftime("%H:%M:%S"),
                        "Kết quả": msg,
                    },
                )
                if ok and changed_status:
                    result["applied"] += 1
                elif not ok:
                    result["errors"] += 1
                continue

            if plan_type != STAFF_PLAN_LONG_LEAVE or end_d is None:
                continue
            if state == STAFF_PLAN_DONE:
                continue

            emp_key = normalize_login_name(employee)
            current_status = status_map.get(emp_key, EMPLOYMENT_STATUS_ACTIVE)
            if today < start_d:
                if state not in {STAFF_PLAN_PENDING, STAFF_PLAN_ERROR}:
                    update_staff_schedule_plan_row(row_idx, {"Trạng thái": STAFF_PLAN_PENDING})
                continue

            # V92.6.84: Đã nghỉ việc là trạng thái cuối cùng. Không để kế hoạch nghỉ dài hạn
            # chuyển ngược thành Tạm nghỉ / Đang làm việc sau khi kế hoạch Nghỉ việc đã áp dụng.
            if current_status == EMPLOYMENT_STATUS_LEFT:
                update_staff_schedule_plan_row(
                    row_idx,
                    {
                        "Trạng thái": STAFF_PLAN_DONE,
                        "Ngày áp dụng": now.strftime("%d/%m/%Y"),
                        "Giờ áp dụng": now.strftime("%H:%M:%S"),
                        "Kết quả": f"Bỏ qua Nghỉ dài hạn vì {employee} đã ở trạng thái Đã nghỉ việc.",
                    },
                )
                continue

            if start_d <= today < end_d:
                # Đã đúng trạng thái và kế hoạch đã Active thì không ghi Sheets lặp lại mỗi rerun.
                if current_status == EMPLOYMENT_STATUS_TEMP and state == STAFF_PLAN_ACTIVE:
                    continue
                ok = True
                msg = f"{employee} đang trong thời gian nghỉ dài hạn."
                changed_status = current_status != EMPLOYMENT_STATUS_TEMP
                if changed_status:
                    ok, msg = set_employee_employment_status(
                        employee, EMPLOYMENT_STATUS_TEMP, "SYSTEM - LỊCH HẸN NHÂN SỰ"
                    )
                    if ok:
                        status_map[emp_key] = EMPLOYMENT_STATUS_TEMP
                update_staff_schedule_plan_row(
                    row_idx,
                    {
                        "Trạng thái": STAFF_PLAN_ACTIVE if ok else STAFF_PLAN_ERROR,
                        "Ngày áp dụng": now.strftime("%d/%m/%Y"),
                        "Giờ áp dụng": now.strftime("%H:%M:%S"),
                        "Kết quả": msg,
                    },
                )
                if ok and changed_status:
                    result["applied"] += 1
                elif not ok:
                    result["errors"] += 1
                continue

            # today >= ngày bắt đầu quay lại làm.
            ok = True
            msg = f"{employee} đến ngày quay lại làm việc."
            if current_status != EMPLOYMENT_STATUS_ACTIVE:
                ok, msg = set_employee_employment_status(
                    employee, EMPLOYMENT_STATUS_ACTIVE, "SYSTEM - LỊCH HẸN NHÂN SỰ"
                )
                if ok:
                    status_map[emp_key] = EMPLOYMENT_STATUS_ACTIVE
            if ok:
                _finish_formal_long_leave_on_planned_return(employee, end_d)
            update_staff_schedule_plan_row(
                row_idx,
                {
                    "Trạng thái": STAFF_PLAN_DONE if ok else STAFF_PLAN_ERROR,
                    "Ngày áp dụng": now.strftime("%d/%m/%Y"),
                    "Giờ áp dụng": now.strftime("%H:%M:%S"),
                    "Kết quả": msg,
                },
            )
            result["applied" if ok else "errors"] += int(current_status != EMPLOYMENT_STATUS_ACTIVE)

        return result
    except Exception:
        return {"applied": 0, "errors": 1}


# V92.6.24: thời hạn đăng ký/hủy không còn hard-code; đọc từ LoaiNghi cột I/J.
DEFAULT_LEAVE_PAGE = "📅 Đăng ký nghỉ phép"
DEFAULT_LEAVE_PAGE_SLUG = "dang-ky-thong-ke-nghi-phep"


# ==========================================================
# V87.5 - RERUN GIỮ NGUYÊN TRANG HIỆN TẠI
# Mọi thao tác nội bộ (Lưu/Sửa/Xóa/Tạm hoãn/Cập nhật...) khi rerun
# phải quay lại đúng trang MENU đang mở, không rơi về trang mặc định.
# ==========================================================
def rerun_current_view():
    # V92.5: mọi rerun nội bộ phải giữ remember_token để Refresh/F5 không mất phiên.
    try:
        _remember = str(st.session_state.get("vera_remember_token", "") or "").strip()
        if (
            st.session_state.get("logged_in")
            and _remember
            and str(st.query_params.get("remember_token", "") or "").strip() != _remember
        ):
            st.query_params["remember_token"] = _remember
    except Exception:
        pass

    try:
        _current_page = str(st.session_state.get("app_page", "") or "")
        _page_slugs = globals().get("PAGE_SLUGS", {}) or {}
        if _current_page and _current_page in _page_slugs:
            _slug = str(_page_slugs.get(_current_page, "") or "").strip()
            if _slug and str(st.query_params.get("page", "") or "").strip() != _slug:
                st.query_params["page"] = _slug
    except Exception:
        pass

    # Gọi trực tiếp API Streamlit để tránh bị thay thế đệ quy khi chuẩn hóa code.
    getattr(st, "rerun")()


def _set_default_page_after_login(role):
    """Lễ tân/Quản lý/Nhân viên luôn mở trang Đăng ký nghỉ phép sau đăng nhập."""
    role_norm = str(role or '').strip().lower()
    if role_norm in {"letan", "quanly", "nhanvien", "leader"}:
        st.session_state.app_page = DEFAULT_LEAVE_PAGE
        try:
            st.query_params["page"] = DEFAULT_LEAVE_PAGE_SLUG
        except Exception:
            pass

def _parse_birthday_date(value):
    """Đọc ngày sinh từ dd/mm/yyyy, dd-mm-yyyy, serial Excel; chấp nhận cả dd/mm."""
    parsed = _parse_vn_date(value)
    if parsed is not None:
        return parsed
    text = str(value or '').strip()
    if not text:
        return None
    for fmt in ('%d/%m', '%d-%m'):
        try:
            tmp = datetime.strptime(text, fmt)
            return date(2000, tmp.month, tmp.day)
        except Exception:
            pass
    return None

def get_month_birthdays(credentials_df, month=None):
    """Danh sách sinh nhật trong tháng của nhanvien/letan/locker, sắp theo ngày sinh."""
    if credentials_df is None or credentials_df.empty:
        return []
    month = int(month or get_vn_today().month)
    rows = []
    for _, r in credentials_df.iterrows():
        role = str(r.get('Phân quyền', '')).strip().lower()
        if role not in BIRTHDAY_EMPLOYEE_ROLES:
            continue
        dob = _parse_birthday_date(r.get('Ngày sinh', ''))
        if dob is None or dob.month != month:
            continue
        system_name = str(r.get('Tên nhân viên', '')).strip()
        full_name = str(r.get('Họ và tên đầy đủ', '')).strip()
        display_name = full_name or system_name
        if not display_name:
            continue
        rows.append({
            'Tên nhân viên': system_name,
            'Họ và tên': display_name,
            'Ngày sinh': f"{dob.day:02d}/{dob.month:02d}",
            'Ngày': dob.day,
            'Vai trò': role,
        })
    rows.sort(key=lambda x: (x['Ngày'], normalize_login_name(x['Họ và tên'])))
    return rows

def _get_birthday_notice_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_MAT_KHAU_ID)
    ws = _get_or_create_worksheet(ss, BIRTHDAY_NOTICE_WORKSHEET, rows=1000, cols=6)
    header = _gs_call_with_backoff(ws.row_values, 1)
    wanted = ["Tài khoản", "Ngày", "Số lần đăng nhập", "Tạm tắt hôm nay"]
    if header[:4] != wanted:
        gspread_update_range(ws, 'A1:D1', [wanted])
    return ws

def register_birthday_notice_login(username):
    """Tăng bộ đếm đúng 1 lần cho một lần đăng nhập; trả về (count, muted)."""
    today_key = get_vn_today().isoformat()
    user_key = normalize_login_name(username)
    try:
        ws = _get_birthday_notice_worksheet()
        if ws is None:
            return 1, False
        vals = _gs_call_with_backoff(ws.get_all_values)
        found_row = None
        count = 0
        muted = False
        for idx, row in enumerate(vals[1:], start=2):
            if len(row) < 2:
                continue
            if normalize_login_name(row[0]) == user_key and str(row[1]).strip() == today_key:
                found_row = idx
                try:
                    count = int(float(str(row[2]).strip() or '0')) if len(row) > 2 else 0
                except Exception:
                    count = 0
                muted = str(row[3]).strip().casefold() in {'1','true','yes','x','tat','tắt'} if len(row) > 3 else False
                break
        count += 1
        if found_row:
            gspread_update_range(ws, f'C{found_row}', [[count]])
        else:
            _gs_call_with_backoff(ws.append_row, [str(username), today_key, count, ''], value_input_option='USER_ENTERED')
        return count, muted
    except Exception:
        # Nếu Google Sheets tạm lỗi, vẫn cho hiện thông báo trong phiên hiện tại.
        return 1, False

def mute_birthday_notice_today(username):
    """Tạm tắt thông báo sinh nhật cho tài khoản hiện tại đến hết ngày hôm nay."""
    today_key = get_vn_today().isoformat()
    user_key = normalize_login_name(username)
    try:
        ws = _get_birthday_notice_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets."
        vals = _gs_call_with_backoff(ws.get_all_values)
        found_row = None
        count = 0
        for idx, row in enumerate(vals[1:], start=2):
            if len(row) >= 2 and normalize_login_name(row[0]) == user_key and str(row[1]).strip() == today_key:
                found_row = idx
                try:
                    count = int(float(str(row[2]).strip() or '0')) if len(row) > 2 else 0
                except Exception:
                    count = 0
                break
        if found_row:
            gspread_update_range(ws, f'D{found_row}', [["1"]])
        else:
            _gs_call_with_backoff(ws.append_row, [str(username), today_key, max(1, count), '1'], value_input_option='USER_ENTERED')
        return True, "Đã tạm tắt thông báo sinh nhật đến hết hôm nay."
    except Exception as e:
        return False, f"Không thể tạm tắt thông báo: {e}"

def render_birthday_login_notice(credentials_df):
    """Hiện thông báo trong ngày 1-5, tối đa ở 3 lần đăng nhập đầu mỗi ngày."""
    role = str(st.session_state.get('current_role', '')).strip().lower()
    if role not in BIRTHDAY_VIEWER_ROLES:
        st.session_state.birthday_login_event = False
        return
    today = get_vn_today()
    if today.day not in BIRTHDAY_NOTICE_DAYS:
        st.session_state.birthday_login_event = False
        return
    birthdays = get_month_birthdays(credentials_df, today.month)
    if not birthdays:
        st.session_state.birthday_login_event = False
        return
    # Chỉ tăng số lần khi đây thực sự là một phiên vừa đăng nhập.
    if st.session_state.get('birthday_login_event', False):
        count, muted = register_birthday_notice_login(st.session_state.get('current_user', ''))
        st.session_state.birthday_notice_count_today = count
        st.session_state.birthday_notice_muted_today = muted
        st.session_state.birthday_login_event = False
    count = int(st.session_state.get('birthday_notice_count_today', 999) or 999)
    muted = bool(st.session_state.get('birthday_notice_muted_today', False))
    if muted or count > BIRTHDAY_NOTICE_MAX_LOGINS_PER_DAY:
        return

    role_labels = {'nhanvien': 'Nhân viên', 'leader': 'Leader', 'letan': 'Lễ tân', 'locker': 'Locker'}
    lines = []
    for b in birthdays:
        role_label = role_labels.get(b['Vai trò'], b['Vai trò'])
        lines.append(f"🎂 **{b['Họ và tên']}** — {b['Ngày sinh']} — {role_label}")
    st.info("🎉 **SINH NHẬT TRONG THÁNG %02d**\n\n%s" % (today.month, "\n\n".join(lines)))
    c_notice, c_mute = st.columns([4, 1])
    with c_notice:
        st.caption(f"Thông báo này xuất hiện trong ngày 01–05 và tối đa ở 3 lần đăng nhập đầu mỗi ngày. Hôm nay: lần {count}/3.")
    with c_mute:
        if st.button("🔕 Tạm tắt hôm nay", use_container_width=True, key=f"mute_birthday_{today.isoformat()}"):
            ok, msg = mute_birthday_notice_today(st.session_state.get('current_user', ''))
            if ok:
                st.session_state.birthday_notice_muted_today = True
                st.toast(msg)
                rerun_current_view()
            else:
                st.error(msg)

def render_manual_birthday_check(credentials_df, key_prefix="birthday_manual"):
    """Nút chủ động xem sinh nhật tháng hiện tại, dùng cho mọi vai trò."""
    today = get_vn_today()
    state_key = f"{key_prefix}_show_{today.year}_{today.month}"
    if st.button("🎂 Kiểm tra sinh nhật tháng này", use_container_width=True, key=f"{key_prefix}_button_{today.year}_{today.month}", disabled=not action_access("birthday_check")):
        st.session_state[state_key] = not bool(st.session_state.get(state_key, False))
    if not st.session_state.get(state_key, False):
        return
    birthdays = get_month_birthdays(credentials_df, today.month)
    if not birthdays:
        st.info(f"Tháng {today.month:02d} hiện chưa có sinh nhật của Nhân viên/Lễ tân/Locker trong hồ sơ.")
        return
    role_labels = {'nhanvien': 'Nhân viên', 'leader': 'Leader', 'letan': 'Lễ tân', 'locker': 'Locker'}
    st.markdown(f"#### 🎉 Sinh nhật tháng {today.month:02d}")
    for b in birthdays:
        st.markdown(f"- 🎂 **{b['Họ và tên']}** — {b['Ngày sinh']} — {role_labels.get(b['Vai trò'], b['Vai trò'])}")


@st.cache_resource
def get_gspread_client():
    """Google API client phù hợp cả Streamlit Cloud lẫn Cloud Run.

    Ưu tiên: GOOGLE_SERVICE_ACCOUNT_JSON -> st.secrets[gcp_service_account]
    -> Application Default Credentials của Cloud Run service account.
    """
    try:
        scope = [
            "https://www.googleapis.com/auth/spreadsheets",
            "https://www.googleapis.com/auth/drive",
        ]
        env_json = str(os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")).strip()
        if env_json:
            creds_dict = json.loads(env_json)
            creds = Credentials.from_service_account_info(creds_dict, scopes=scope)
            return gspread.authorize(creds)
        try:
            creds_dict = dict(st.secrets["gcp_service_account"])
        except Exception:
            creds_dict = {}
        if creds_dict:
            creds = Credentials.from_service_account_info(creds_dict, scopes=scope)
            return gspread.authorize(creds)
        # Cloud Run: có thể dùng chính runtime service account (ADC).
        import google.auth
        creds, _ = google.auth.default(scopes=scope)
        return gspread.authorize(creds)
    except Exception:
        return None


def get_smtp_sender_credentials():
    """Lấy Gmail sender/app-password từ Secret Manager env hoặc Streamlit secrets."""
    sender_email = str(os.getenv("SMTP_SENDER_EMAIL", "veraspabienhoa@gmail.com")).strip()
    sender_pass = str(os.getenv("SMTP_APP_PASSWORD", "")).strip()
    if not sender_pass:
        try:
            sender_pass = str(st.secrets.get("smtp_app_password", "")).strip()
        except Exception:
            pass
    return sender_email, sender_pass


def _auto_penalty_cc_emails_v92673(credentials_df=None):
    """CC Auto phạt: email hệ thống/Admin + toàn bộ quanly/letan đang làm việc."""
    emails = {"veraspabienhoa@gmail.com"}
    try:
        smtp_email, _ = get_smtp_sender_credentials()
        if smtp_email and "@" in smtp_email:
            emails.add(smtp_email.strip())
    except Exception:
        pass

    try:
        creds = (
            credentials_df
            if isinstance(credentials_df, pd.DataFrame)
            else load_credentials_recent()
        )
        if isinstance(creds, pd.DataFrame) and not creds.empty:
            if "Phân quyền" in creds.columns and "Email" in creds.columns:
                d = creds[
                    creds["Phân quyền"].astype(str).str.strip().str.lower()
                    .isin({"quanly", "letan"})
                ].copy()
                if "Tên nhân viên" in d.columns:
                    try:
                        status_map = load_employment_status_map()
                        d = d[d["Tên nhân viên"].astype(str).apply(
                            lambda n: status_map.get(
                                normalize_login_name(n), EMPLOYMENT_STATUS_ACTIVE
                            ) == EMPLOYMENT_STATUS_ACTIVE
                        )]
                    except Exception:
                        pass
                for value in d["Email"].astype(str).tolist():
                    value = value.strip()
                    if value and "@" in value:
                        emails.add(value)
    except Exception:
        pass
    return sorted(emails)


def _append_auto_update_email_log_v92674(employee, email_to, cc_text, reason, status, detail, count=1):
    """Lưu bằng chứng gửi email Auto Update vào worksheet AutoUpdateEmailLog."""
    try:
        client = get_gspread_client()
        if not client:
            return
        ss = client.open_by_key(SHEET_DU_PHONG_ID)
        try:
            ws = ss.worksheet("AutoUpdateEmailLog")
        except Exception:
            ws = ss.add_worksheet(title="AutoUpdateEmailLog", rows=2000, cols=12)
        wanted = ["Ngày", "Tên nhân viên", "Email", "CC", "Số dòng mới", "Lý do", "Trạng thái", "Thời gian gửi", "Chi tiết"]
        header = _gs_call_with_backoff(ws.row_values, 1)
        if header[:len(wanted)] != wanted:
            gspread_update_range(ws, "A1:I1", [wanted])
        now_vn = datetime.now(VN_TZ)
        row = [
            now_vn.strftime("%d/%m/%Y"), str(employee or ""), str(email_to or ""),
            str(cc_text or ""), int(count or 0), str(reason or ""), str(status or ""),
            now_vn.strftime("%H:%M:%S"), str(detail or ""),
        ]
        target = len(_gs_call_with_backoff(ws.get_all_values)) + 1
        gspread_update_range(ws, f"A{target}:I{target}", [row])
    except Exception:
        pass


def send_auto_penalty_notification_email_v92673(
    employee_username,
    work_date,
    leave_reason,
    leave_detail,
    penalty_amount,
    actor="AUTO UPDATE",
    credentials_df=None,
):
    """Gửi email ngay khi Auto Update ghi thành công một vi phạm có tiền phạt > 0."""
    try:
        amount = float(penalty_amount or 0)
    except Exception:
        amount = 0.0
    if amount <= 0:
        return True, "Không gửi email vì Phạt vi phạm = 0."

    _mail_cfg_v92675 = load_auto_email_config_v92675()
    if _mail_cfg_v92675.get("paused"):
        return False, (
            "Gửi mail tự động của Auto Update đang TẠM DỪNG bởi Admin; "
            "dòng phạt vẫn được lưu và có thể gửi bù sau khi mở lại."
        )

    try:
        # V92.6.80: khi Auto Check Manual gửi nhiều người, hồ sơ được đọc 1 lần
        # rồi truyền dùng chung cho toàn bộ batch. Scheduler/luồng đơn vẫn tự đọc mới.
        creds = (
            credentials_df
            if isinstance(credentials_df, pd.DataFrame) and not credentials_df.empty
            else load_credentials_fresh_for_email()
        )
        to_email = latest_email_from_credentials(creds, employee_username)
        if not to_email or "@" not in to_email:
            return False, f"{employee_username} chưa có Email hợp lệ trong hồ sơ."

        smtp_email, smtp_password = get_smtp_sender_credentials()
        if not smtp_email or not smtp_password:
            return False, "Chưa cấu hình SMTP để gửi email Auto Update."

        emp_profile = _credential_profile_by_username(employee_username, creds)
        emp_name = str(
            emp_profile.get("Họ và tên đầy đủ", "") or employee_username
        ).strip()
        date_text = normalize_schedule_date(work_date) or str(work_date or "")
        reason_text = clean_leave_reason_display(leave_reason)
        detail_text = str(leave_detail or "").strip()

        cc_emails = [
            x for x in _auto_penalty_cc_emails_v92673(creds)
            if normalize_login_name(x) != normalize_login_name(to_email)
        ]

        body_html = f"""
        <html><body style='font-family:Arial,sans-serif'>
        <h3>VERA SPA · THÔNG BÁO AUTO UPDATE VI PHẠM</h3>
        <p>Hệ thống đã tự động ghi nhận một vi phạm của <b>{html.escape(emp_name)}</b>.</p>
        <p><b>Ngày:</b> {html.escape(date_text)}</p>
        <p><b>Lý do:</b> {html.escape(reason_text)}</p>
        <p><b>Chi tiết:</b> {html.escape(detail_text)}</p>
        <p><b>Phạt vi phạm:</b> {amount:,.0f} VNĐ</p>
        <p><b>Nguồn:</b> {html.escape(str(actor or 'AUTO UPDATE'))}</p>
        <p>Vui lòng đăng nhập hệ thống VERA để kiểm tra chi tiết.</p>
        </body></html>
        """

        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"[VERA SPA] Auto Update vi phạm · {employee_username} · {date_text}"
        msg["From"] = f"VERA SPA <{smtp_email}>"
        msg["To"] = to_email
        if cc_emails:
            msg["Cc"] = ", ".join(cc_emails)
        msg.attach(MIMEText(body_html, "html", "utf-8"))

        recipients = [to_email] + cc_emails
        server = smtplib.SMTP("smtp.gmail.com", 587)
        server.starttls()
        server.login(smtp_email, smtp_password)
        server.sendmail(smtp_email, recipients, msg.as_string())
        server.quit()
        return True, (
            f"Đã gửi email Auto Update tới {employee_username} ({to_email})"
            + (f"; CC {len(cc_emails)} địa chỉ." if cc_emails else ".")
        )
    except Exception as e:
        return False, f"Lỗi gửi email Auto Update: {e}"


def _credential_profile_by_username(username, credentials_df=None):
    """Lấy hồ sơ mới nhất theo Tên nhân viên."""
    try:
        d = credentials_df if isinstance(credentials_df, pd.DataFrame) else load_credentials_fresh_for_email()
        if d is None or d.empty or "Tên nhân viên" not in d.columns:
            return {}
        key = normalize_login_name(username)
        hit = d[
            d["Tên nhân viên"].astype(str).apply(normalize_login_name).eq(key)
        ]
        if hit.empty:
            return {}
        return hit.iloc[0].to_dict()
    except Exception:
        return {}


def send_reception_leave_registration_email(
    receptionist_username,
    employee_username,
    employee_role,
    start_date,
    end_date,
    leave_reason,
    leave_detail="",
):
    """
    V92.6.3:
    Lễ tân đăng ký lịch nghỉ cho nhanvien/leader -> gửi email tới nhân viên.
    Header From + Reply-To dùng Email trong hồ sơ của chính user Lễ tân.
    SMTP vẫn xác thực bằng tài khoản SMTP hệ thống để không lưu mật khẩu email cá nhân trong app.py.
    """
    try:
        fresh_creds = load_credentials_fresh_for_email()
        rec = _credential_profile_by_username(receptionist_username, fresh_creds)
        emp = _credential_profile_by_username(employee_username, fresh_creds)

        rec_role = str(rec.get("Phân quyền", "") or "").strip().lower()
        target_role = str(employee_role or emp.get("Phân quyền", "") or "").strip().lower()
        if rec_role != "letan":
            return False, "Chỉ gửi email tự động khi người đăng ký là tài khoản Lễ tân."
        if target_role not in {"nhanvien", "leader"}:
            return False, "Email tự động này chỉ áp dụng cho Nhân viên/Leader."

        receptionist_email = str(rec.get("Email", "") or "").strip()
        employee_email = str(emp.get("Email", "") or "").strip()
        if not receptionist_email or "@" not in receptionist_email:
            return False, f"Tài khoản Lễ tân {receptionist_username} chưa có Email hợp lệ trong hồ sơ."
        if not employee_email or "@" not in employee_email:
            return False, f"Tài khoản {employee_username} chưa có Email hợp lệ trong hồ sơ."

        smtp_email, smtp_password = get_smtp_sender_credentials()
        if not smtp_email or not smtp_password:
            return False, "Chưa cấu hình SMTP để gửi email."

        s = start_date.date() if isinstance(start_date, datetime) else start_date
        e = end_date.date() if isinstance(end_date, datetime) else end_date
        if not isinstance(s, date) or not isinstance(e, date):
            return False, "Ngày nghỉ không hợp lệ."

        if s == e:
            date_text = s.strftime("%d/%m/%Y")
        else:
            date_text = f"{s.strftime('%d/%m/%Y')} - {e.strftime('%d/%m/%Y')}"

        receptionist_name = str(
            rec.get("Họ và tên đầy đủ", "") or receptionist_username
        ).strip()
        employee_name = str(
            emp.get("Họ và tên đầy đủ", "") or employee_username
        ).strip()

        # Nội dung phải BẮT ĐẦU bằng "Lễ Tân..."
        body_html = f"""Lễ Tân Vera Spa thông báo lịch nghỉ đã được đăng ký cho {html.escape(employee_name)}.
<br><br>
<b>Ngày nghỉ:</b> {html.escape(date_text)}<br>
<b>Lý do nghỉ:</b> {html.escape(clean_leave_reason_display(leave_reason))}<br>
"""
        if str(leave_detail or "").strip():
            body_html += f"<b>Chi tiết/Ghi chú:</b> {html.escape(str(leave_detail).strip())}<br>"
        body_html += (
            f"<b>Người đăng ký:</b> {html.escape(receptionist_name)}"
            f" ({html.escape(receptionist_username)})<br><br>"
            "Vui lòng đăng nhập hệ thống VERA để kiểm tra lại lịch nghỉ."
        )

        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Thông báo lịch nghỉ · {employee_username} · {date_text}"
        # Địa chỉ hiển thị gửi và Reply-To đều là Email của user Lễ tân.
        msg["From"] = f"Lễ Tân Vera Spa <{receptionist_email}>"
        msg["Reply-To"] = receptionist_email
        msg["Sender"] = smtp_email
        msg["To"] = employee_email
        msg.attach(MIMEText(body_html, "html", "utf-8"))

        server = smtplib.SMTP("smtp.gmail.com", 587)
        server.starttls()
        server.login(smtp_email, smtp_password)
        server.sendmail(
            smtp_email,
            [employee_email],
            msg.as_string(),
        )
        server.quit()
        return True, (
            f"Đã gửi email thông báo tới {employee_username} ({employee_email}) "
            f"với địa chỉ Lễ tân {receptionist_email}."
        )
    except Exception as e:
        return False, f"Không gửi được email thông báo lịch nghỉ: {e}"



LEAVE_AUDIT_NOTICE_WORKSHEET = "ThongBaoSuaXoaLichNghi"
LEAVE_AUDIT_NOTICE_HEADERS = [
    "ID", "Hành động", "Tài khoản thao tác", "Vai trò",
    "Tên nhân viên", "Trước", "Sau",
    "Ngày cập nhật", "Giờ cập nhật", "Email", "Trạng thái email",
]
LEAVE_AUDIT_ADMIN_EMAIL = "veraspabienhoa@gmail.com"
LEAVE_AUDIT_FIELDS = [
    "Ngày", "Thứ ngày", "Tên nhân viên", "Lý do nghỉ", "Loại nghỉ",
    "Chi tiết", "Số ngày tính", "Số ngày phép cộng dồn",
    "Phạt vi phạm", "Ngày cập nhật", "Giờ cập nhật", "Người cập nhật",
]


def _leave_audit_snapshot(row):
    if row is None:
        return {}
    getv = row.get if hasattr(row, "get") else (lambda _k, _d="": _d)
    out = {}
    for field in LEAVE_AUDIT_FIELDS:
        value = getv(field, "")
        try:
            if pd.isna(value):
                value = ""
        except Exception:
            pass
        if isinstance(value, (datetime, date)):
            value = value.strftime("%d/%m/%Y")
        out[field] = value
    return out


def _leave_audit_compact_text(snapshot):
    if not snapshot:
        return "(ĐÃ XÓA / không còn bản ghi)"
    fields = [
        ("Ngày", snapshot.get("Ngày", "")),
        ("Nhân viên", snapshot.get("Tên nhân viên", "")),
        ("Lý do", snapshot.get("Lý do nghỉ", "")),
        ("Loại", snapshot.get("Loại nghỉ", "")),
        ("Chi tiết", snapshot.get("Chi tiết", "")),
        ("Số ngày", snapshot.get("Số ngày tính", "")),
        ("Phạt", snapshot.get("Phạt vi phạm", "")),
    ]
    return " · ".join(f"{k}: {v}" for k, v in fields if str(v).strip())


def _get_leave_audit_notice_ws():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_DU_PHONG_ID)
    ws = _get_or_create_worksheet(
        ss,
        LEAVE_AUDIT_NOTICE_WORKSHEET,
        rows=5000,
        cols=len(LEAVE_AUDIT_NOTICE_HEADERS),
    )
    try:
        header = _gs_call_with_backoff(ws.row_values, 1)
        if header[:len(LEAVE_AUDIT_NOTICE_HEADERS)] != LEAVE_AUDIT_NOTICE_HEADERS:
            gspread_update_range(
                ws,
                f"A1:K1",
                [LEAVE_AUDIT_NOTICE_HEADERS],
            )
    except Exception:
        pass
    return ws


def send_admin_leave_audit_email(action, actor, actor_role, before_row, after_row=None):
    """Email chi tiết TRƯỚC/SAU tới veraspabienhoa@gmail.com."""
    smtp_email, smtp_password = get_smtp_sender_credentials()
    if not smtp_email or not smtp_password:
        return False, "Chưa cấu hình SMTP."

    before = _leave_audit_snapshot(before_row)
    after = _leave_audit_snapshot(after_row)
    employee = str(
        after.get("Tên nhân viên", "")
        or before.get("Tên nhân viên", "")
    ).strip()
    action_label = "SỬA" if str(action).lower() == "edit" else "XÓA"

    def _html_snapshot(title, snap):
        if not snap:
            return (
                f"<h4>{html.escape(title)}</h4>"
                "<p><b>(ĐÃ XÓA / không còn bản ghi)</b></p>"
            )
        rows = []
        for field in LEAVE_AUDIT_FIELDS:
            value = snap.get(field, "")
            if str(value).strip():
                rows.append(
                    "<tr>"
                    f"<td style='border:1px solid #ddd;padding:6px'><b>{html.escape(field)}</b></td>"
                    f"<td style='border:1px solid #ddd;padding:6px'>{html.escape(str(value))}</td>"
                    "</tr>"
                )
        return (
            f"<h4>{html.escape(title)}</h4>"
            "<table style='border-collapse:collapse;width:100%'>"
            + "".join(rows)
            + "</table>"
        )

    try:
        subject = (
            f"[VERA SPA] {action_label} lịch nghỉ · {employee or 'Nhân viên'} "
            f"· bởi {actor}"
        )
        body = f"""
        <html><body style='font-family:Arial,sans-serif'>
        <h3>{action_label} LỊCH NGHỈ</h3>
        <p><b>Người thao tác:</b> {html.escape(str(actor))}</p>
        <p><b>Vai trò:</b> {html.escape(str(actor_role))}</p>
        <p><b>Thời điểm:</b> {datetime.now(VN_TZ).strftime('%d/%m/%Y %H:%M:%S')}</p>
        {_html_snapshot("TRƯỚC KHI THAO TÁC", before)}
        {_html_snapshot("SAU KHI THAO TÁC", after)}
        </body></html>
        """
        msg = MIMEMultipart("alternative")
        msg["From"] = f"VERA SPA <{smtp_email}>"
        msg["To"] = LEAVE_AUDIT_ADMIN_EMAIL
        msg["Subject"] = subject
        msg.attach(MIMEText(body, "html", "utf-8"))

        server = smtplib.SMTP("smtp.gmail.com", 587)
        server.starttls()
        server.login(smtp_email, smtp_password)
        server.sendmail(
            smtp_email,
            [LEAVE_AUDIT_ADMIN_EMAIL],
            msg.as_string(),
        )
        server.quit()
        return True, f"Đã gửi email tới {LEAVE_AUDIT_ADMIN_EMAIL}."
    except Exception as e:
        return False, f"Lỗi gửi email audit: {e}"


@st.cache_data(ttl=15, show_spinner=False)
def load_admin_leave_audit_notices(limit=10):
    try:
        ws = _get_leave_audit_notice_ws()
        if ws is None:
            return []
        values = _gs_call_with_backoff(ws.get_all_values)
        if len(values) <= 1:
            return []
        rows = []
        for raw in values[1:]:
            vals = list(raw[:len(LEAVE_AUDIT_NOTICE_HEADERS)]) + [""] * max(
                0, len(LEAVE_AUDIT_NOTICE_HEADERS) - len(raw)
            )
            item = dict(zip(LEAVE_AUDIT_NOTICE_HEADERS, vals))
            if str(item.get("ID", "")).strip():
                rows.append(item)
        return list(reversed(rows[-max(1, int(limit)):]))
    except Exception:
        return []


def notify_admin_leave_schedule_change(action, actor, actor_role, before_row, after_row=None):
    """
    Mỗi lần letan/quanly sửa hoặc xóa:
    1) gửi email tới Admin,
    2) ghi 1 notification chi tiết để tài khoản Admin nhận trên app.
    Không rollback thay đổi lịch nếu email/notification gặp lỗi.
    """
    actor_role = str(actor_role or "").strip().lower()
    if actor_role not in {"letan", "quanly"}:
        return True, ""

    before = _leave_audit_snapshot(before_row)
    after = _leave_audit_snapshot(after_row)
    action_label = "SỬA" if str(action).lower() == "edit" else "XÓA"
    now = datetime.now(VN_TZ)
    raw_id = "|".join([
        action_label,
        str(actor),
        json.dumps(before, ensure_ascii=False, sort_keys=True, default=str),
        json.dumps(after, ensure_ascii=False, sort_keys=True, default=str),
        now.isoformat(),
    ])
    audit_id = hashlib.sha1(raw_id.encode("utf-8")).hexdigest()[:24]

    email_ok, email_msg = send_admin_leave_audit_email(
        action, actor, actor_role, before, after
    )

    notice_ok = False
    notice_msg = ""
    try:
        ws = _get_leave_audit_notice_ws()
        if ws is None:
            notice_msg = "Không kết nối được sheet thông báo."
        else:
            employee = str(
                after.get("Tên nhân viên", "")
                or before.get("Tên nhân viên", "")
            ).strip()
            row = [
                audit_id,
                action_label,
                str(actor or "").strip(),
                actor_role,
                employee,
                json.dumps(before, ensure_ascii=False, default=str),
                json.dumps(after, ensure_ascii=False, default=str),
                now.strftime("%d/%m/%Y"),
                now.strftime("%H:%M:%S"),
                LEAVE_AUDIT_ADMIN_EMAIL,
                ("SUCCESS" if email_ok else f"ERROR: {email_msg}")[:500],
            ]
            _gs_call_with_backoff(
                ws.append_row,
                row,
                value_input_option="USER_ENTERED",
            )
            try:
                load_admin_leave_audit_notices.clear()
            except Exception:
                pass
            notice_ok = True
    except Exception as e:
        notice_msg = f"Lỗi ghi notification: {e}"

    ok = bool(email_ok and notice_ok)
    detail = " | ".join(
        x for x in [
            email_msg,
            ("Đã tạo thông báo cho Admin." if notice_ok else notice_msg),
        ] if x
    )
    return ok, detail


def _admin_leave_audit_notice_message(item):
    try:
        before = json.loads(str(item.get("Trước", "") or "{}"))
    except Exception:
        before = {}
    try:
        after = json.loads(str(item.get("Sau", "") or "{}"))
    except Exception:
        after = {}
    action = str(item.get("Hành động", "") or "").strip()
    actor = str(item.get("Tài khoản thao tác", "") or "").strip()
    role = str(item.get("Vai trò", "") or "").strip()
    when = " ".join([
        str(item.get("Ngày cập nhật", "") or "").strip(),
        str(item.get("Giờ cập nhật", "") or "").strip(),
    ]).strip()
    return (
        f"🔔 {role.upper()} · {actor} đã {action} lịch nghỉ"
        + (f" lúc {when}" if when else "")
        + f". TRƯỚC: {_leave_audit_compact_text(before)}"
        + f" | SAU: {_leave_audit_compact_text(after)}"
    )


