@st.cache_data(ttl=60, show_spinner=False)
def load_shared_input_grants_v92690():
    """Đọc các quyền chia sẻ form. Trả DataFrame, không phụ thuộc quyền hiện tại."""
    cols = list(SHARED_INPUT_HEADERS_V92690)
    try:
        ws = _get_shared_input_worksheet_v92690()
        if ws is None:
            return pd.DataFrame(columns=cols)
        values = _gs_call_with_backoff(ws.get_all_values)
        if not values or len(values) < 2:
            return pd.DataFrame(columns=cols)
        header = [str(x).strip() for x in values[0]]
        rows = []
        for rr in values[1:]:
            row = list(rr) + [""] * max(0, len(header) - len(rr))
            rows.append({header[i]: row[i] for i in range(min(len(header), len(row)))})
        df = pd.DataFrame(rows)
        for c in cols:
            if c not in df.columns:
                df[c] = ""
        df["__row"] = range(2, 2 + len(df))
        return df[cols + ["__row"]].copy()
    except Exception:
        return pd.DataFrame(columns=cols + ["__row"])


def _clear_shared_input_cache_v92690():
    try:
        load_shared_input_grants_v92690.clear()
    except Exception:
        pass


def _parse_shared_input_date_v92690(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value or "").strip()
    if not text:
        return None
    for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d", "%m/%d/%Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except Exception:
            pass
    try:
        parsed = pd.to_datetime(text, dayfirst=True, errors="coerce")
        if pd.notna(parsed):
            return parsed.date()
    except Exception:
        pass
    return None


def _shared_input_row_active_v92690(row, today=None):
    today = today or get_vn_today()
    status = str(row.get("Trạng thái", "") or "").strip().upper()
    if status != SHARED_INPUT_ACTIVE_V92690:
        return False
    start_d = _parse_shared_input_date_v92690(row.get("Từ ngày", ""))
    end_d = _parse_shared_input_date_v92690(row.get("Đến ngày", ""))
    if start_d is not None and today < start_d:
        return False
    if end_d is not None and today > end_d:
        return False
    return True


def shared_input_grants_for_user_v92690(username=None, active_only=True):
    username = str(
        username if username is not None else st.session_state.get("current_user", "")
    ).strip()
    user_key = normalize_login_name(username)
    if not user_key:
        return pd.DataFrame(columns=SHARED_INPUT_HEADERS_V92690 + ["__row"])
    df = load_shared_input_grants_v92690()
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=SHARED_INPUT_HEADERS_V92690 + ["__row"])
    mask = df["Tài khoản"].astype(str).apply(normalize_login_name).eq(user_key)
    out = df[mask].copy()
    if active_only and not out.empty:
        out = out[out.apply(_shared_input_row_active_v92690, axis=1)].copy()
    return out


def has_shared_input_form_access_v92690(form_key, username=None):
    form_key = str(form_key or "").strip()
    if form_key not in SHAREABLE_INPUT_FORMS_V92690:
        return False
    grants = shared_input_grants_for_user_v92690(username=username, active_only=True)
    if grants.empty:
        return False
    return grants["Mã bảng"].astype(str).str.strip().eq(form_key).any()


def has_shared_input_feature_access_v92690(feature, username=None):
    feature = str(feature or "").strip()
    form_keys = SHARED_INPUT_FEATURE_TO_FORMS_V92690.get(feature, set())
    if not form_keys:
        return False
    return any(has_shared_input_form_access_v92690(k, username=username) for k in form_keys)


def _shared_input_grant_id_v92690(form_key, username):
    seed = (
        f"{form_key}|{normalize_login_name(username)}|"
        f"{datetime.now(VN_TZ).strftime('%Y%m%d%H%M%S%f')}|{secrets.token_hex(3)}"
    )
    return "SHR-" + hashlib.sha1(seed.encode("utf-8")).hexdigest()[:14].upper()


def grant_shared_input_form_v92690(form_key, username, granted_by, start_date=None, end_date=None, note=""):
    form_key = str(form_key or "").strip()
    username = str(username or "").strip()
    if form_key not in SHAREABLE_INPUT_FORMS_V92690:
        return False, "Bảng nhập liệu không hợp lệ.", ""
    if not username:
        return False, "Vui lòng chọn nhân viên/tài khoản được chia sẻ.", ""
    start_date = start_date or get_vn_today()
    if end_date is not None and end_date < start_date:
        return False, "Ngày hết quyền không được nhỏ hơn ngày bắt đầu.", ""

    existing = shared_input_grants_for_user_v92690(username, active_only=True)
    if not existing.empty and existing["Mã bảng"].astype(str).str.strip().eq(form_key).any():
        hit = existing[existing["Mã bảng"].astype(str).str.strip().eq(form_key)].iloc[-1]
        return True, "Tài khoản này đã có quyền chia sẻ đang hiệu lực cho bảng đã chọn.", str(hit.get("Mã chia sẻ", ""))

    ws = _get_shared_input_worksheet_v92690()
    if ws is None:
        return False, "Không kết nối được Google Sheets để lưu quyền chia sẻ.", ""
    now = datetime.now(VN_TZ)
    grant_id = _shared_input_grant_id_v92690(form_key, username)
    cfg = SHAREABLE_INPUT_FORMS_V92690[form_key]
    row = [
        grant_id,
        form_key,
        cfg.get("label", form_key),
        username,
        SHARED_INPUT_ACTIVE_V92690,
        start_date.strftime("%d/%m/%Y") if start_date else "",
        end_date.strftime("%d/%m/%Y") if end_date else "",
        str(note or "").strip(),
        now.strftime("%d/%m/%Y"),
        now.strftime("%H:%M:%S"),
        str(granted_by or "").strip(),
        "", "", "",
    ]
    try:
        _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        _clear_shared_input_cache_v92690()
        return True, f"Đã chia sẻ bảng '{cfg.get('label', form_key)}' cho {username}.", grant_id
    except Exception as e:
        return False, f"Lỗi lưu quyền chia sẻ: {e}", ""


def revoke_shared_input_grant_v92690(grant_id, revoked_by):
    grant_id = str(grant_id or "").strip()
    if not grant_id:
        return False, "Chưa chọn quyền cần thu hồi."
    df = load_shared_input_grants_v92690()
    if not isinstance(df, pd.DataFrame) or df.empty:
        return False, "Không tìm thấy dữ liệu chia sẻ."
    hit = df[df["Mã chia sẻ"].astype(str).str.strip().eq(grant_id)]
    if hit.empty:
        return False, "Không tìm thấy mã chia sẻ."
    row_idx = int(hit.iloc[-1].get("__row", 0) or 0)
    if row_idx < 2:
        return False, "Dòng dữ liệu chia sẻ không hợp lệ."
    ws = _get_shared_input_worksheet_v92690()
    if ws is None:
        return False, "Không kết nối được Google Sheets."
    now = datetime.now(VN_TZ)
    try:
        # E = Trạng thái; L:M:N = Ngày/Giờ/Người thu hồi.
        gspread_update_range(ws, f"E{row_idx}:E{row_idx}", [[SHARED_INPUT_REVOKED_V92690]])
        gspread_update_range(
            ws, f"L{row_idx}:N{row_idx}",
            [[now.strftime("%d/%m/%Y"), now.strftime("%H:%M:%S"), str(revoked_by or "").strip()]],
        )
        _clear_shared_input_cache_v92690()
        return True, "Đã thu hồi quyền chia sẻ."
    except Exception as e:
        return False, f"Lỗi thu hồi quyền chia sẻ: {e}"


def shared_input_labels_for_current_page_v92690(page_name, username=None):
    grants = shared_input_grants_for_user_v92690(username=username, active_only=True)
    if grants.empty:
        return []
    labels = []
    for _, rr in grants.iterrows():
        form_key = str(rr.get("Mã bảng", "") or "").strip()
        cfg = SHAREABLE_INPUT_FORMS_V92690.get(form_key, {})
        if cfg.get("page") == page_name:
            labels.append(str(cfg.get("label", form_key)))
    return list(dict.fromkeys([x for x in labels if x]))


def has_feature_access(feature, role=None, username=None):
    """Kiểm tra quyền theo thứ tự: Admin -> tài khoản -> vai trò -> mặc định hệ thống."""
    feature = str(feature or '').strip()
    if feature not in FEATURE_DEFINITIONS:
        return False
    role = str(role if role is not None else st.session_state.get('current_role', '')).strip().lower()
    username = str(username if username is not None else st.session_state.get('current_user', '')).strip()
    if role == 'admin':
        return True
    # V92.6.90: quyền chia sẻ form là quyền bổ sung độc lập, có thể mở đúng bảng nhập/lưu
    # ngay cả khi vai trò hoặc quyền riêng thông thường không có feature đó.
    if has_shared_input_feature_access_v92690(feature, username=username):
        return True
    role_cfg, account_cfg = load_feature_permissions()
    account_key = (normalize_login_name(username), feature)
    if normalize_login_name(username) and account_key in account_cfg:
        return bool(account_cfg[account_key])
    role_key = (role, feature)
    if role_key in role_cfg:
        return bool(role_cfg[role_key])
    return feature in DEFAULT_ROLE_FEATURES.get(role, set())


def long_leave_can_use_form(role=None, username=None):
    """Quyền dùng mẫu đơn lấy từ Phân quyền chức năng; account override ưu tiên role."""
    role = str(
        role if role is not None else st.session_state.get("current_role", "")
    ).strip().lower()
    username = (
        str(username).strip()
        if username is not None
        else str(st.session_state.get("current_user", "")).strip()
    )
    return has_feature_access("long_leave_form", role=role, username=username)


def long_leave_can_view_stats(role=None, username=None):
    """Quyền xem thống kê nghỉ dài hạn theo đúng role/account override."""
    role = str(
        role if role is not None else st.session_state.get("current_role", "")
    ).strip().lower()
    username = (
        str(username).strip()
        if username is not None
        else str(st.session_state.get("current_user", "")).strip()
    )
    return has_feature_access("long_leave_stats", role=role, username=username)

def set_long_leave_stats_role_toggle(role, enabled, updated_by):
    """Bật/tắt thống kê riêng cho role nhanvien hoặc leader, giữ nguyên các quyền khác."""
    role = str(role or "").strip().lower()
    if role not in {"nhanvien", "leader"}:
        return False, "Chỉ áp dụng cho vai trò nhanvien hoặc leader."

    allowed = set(get_effective_feature_keys_for_role(role))
    # Luôn giữ quyền vào trang + mẫu đơn cho 2 role này.
    allowed.update({"long_leave", "long_leave_form"})
    if bool(enabled):
        allowed.add("long_leave_stats")
    else:
        allowed.discard("long_leave_stats")

    ok, msg = save_role_feature_permissions(role, sorted(allowed), updated_by)
    if ok:
        _clear_feature_permission_cache()
    return ok, msg


def can_view_employee_penalty():
    """Admin luôn xem; các tài khoản khác theo Phân quyền chức năng."""
    role = str(st.session_state.get("current_role", "")).strip().lower()
    if role == "admin":
        return True
    return has_feature_access("employee_penalty_view")

def _rewrite_feature_permission_scope(scope, target, allowed_features, updated_by, inherit=False):
    """Ghi lại toàn bộ cấu hình của 1 vai trò/tài khoản bằng một lần rewrite sheet."""
    try:
        ws = _get_feature_permission_worksheet()
        if ws is None:
            return False, 'Không kết nối được Google Sheets.'
        values = _gs_call_with_backoff(ws.get_all_values)
        keep = [FEATURE_PERMISSION_HEADERS]
        scope_norm = normalize_login_name(scope)
        target_norm = normalize_login_name(target) if scope_norm == 'account' else str(target).strip().lower()
        for row in values[1:]:
            if len(row) < 2:
                continue
            row_scope = normalize_login_name(row[0])
            row_target = normalize_login_name(row[1]) if row_scope == 'account' else str(row[1]).strip().lower()
            if row_scope == scope_norm and row_target == target_norm:
                continue
            rr = list(row[:7]) + [''] * max(0, 7-len(row))
            keep.append(rr[:7])
        if not inherit:
            now = datetime.now(VN_TZ)
            allowed_set = set(allowed_features or [])
            for key in FEATURE_DEFINITIONS:
                keep.append([
                    scope, str(target).strip(), key, '1' if key in allowed_set else '0',
                    now.strftime('%d/%m/%Y'), now.strftime('%H:%M:%S'), str(updated_by).strip()
                ])
        _gs_call_with_backoff(ws.clear)
        end_row = max(1, len(keep))
        gspread_update_range(ws, f'A1:G{end_row}', keep)
        _clear_feature_permission_cache()
        return True, 'Đã lưu phân quyền chức năng.' if not inherit else 'Đã xóa quyền riêng; tài khoản sẽ dùng quyền theo vai trò.'
    except Exception as e:
        return False, f'Lỗi lưu phân quyền: {e}'

def save_role_feature_permissions(role, allowed_features, updated_by):
    role = str(role or '').strip().lower()
    if role == 'admin':
        return False, 'Quyền Admin luôn được giữ đầy đủ để tránh tự khóa hệ thống.'
    return _rewrite_feature_permission_scope('role', role, allowed_features, updated_by, inherit=False)

def save_account_feature_permissions(username, allowed_features, updated_by, inherit=False):
    if not str(username or '').strip():
        return False, 'Vui lòng chọn tài khoản.'
    return _rewrite_feature_permission_scope('account', str(username).strip(), allowed_features, updated_by, inherit=inherit)


def _permission_keys_in_catalog_order(keys):
    allowed = set(keys or [])
    return [k for k in FEATURE_DEFINITIONS if k in allowed]


def render_grouped_permission_selector(prefix, visible_keys, current_allowed):
    """
    Hiển thị quyền theo nhóm nghiệp vụ. Trả về set feature keys đã chọn.
    Dùng chung cho quyền theo vai trò và quyền riêng từng tài khoản.
    """
    visible = set(visible_keys or [])
    current = set(current_allowed or [])
    selected = set()

    for group_label, group_keys in FEATURE_PERMISSION_GROUPS.items():
        keys = [k for k in group_keys if k in visible]
        if not keys:
            continue
        labels = [FEATURE_DEFINITIONS[k] for k in keys]
        default_labels = [FEATURE_DEFINITIONS[k] for k in keys if k in current]
        safe_group = normalize_login_name(group_label).replace(" ", "_") or "group"
        with st.expander(group_label, expanded=group_label in {"📅 Lịch nghỉ", "👥 Nhân sự"}):
            picked = st.multiselect(
                "Quyền được phép",
                labels,
                default=default_labels,
                filter_mode="contains",
                key=f"{prefix}_{safe_group}",
            )
            label_to_key = {FEATURE_DEFINITIONS[k]: k for k in keys}
            selected.update(label_to_key[x] for x in picked if x in label_to_key)
    return selected


def action_access(feature):
    """Alias ngắn để kiểm tra quyền hành động hiện tại."""
    return has_feature_access(feature)


def get_effective_feature_keys_for_role(role):
    role = str(role or '').strip().lower()
    return [k for k in FEATURE_DEFINITIONS if has_feature_access(k, role=role, username='')]

def _clear_payroll_config_cache():
    """Chỉ xóa cache cấu hình lương, không xóa toàn bộ cache của ứng dụng."""
    try:
        _load_payroll_config_rows_cached.clear()
    except Exception:
        pass


def _clear_leave_data_caches():
    """
    V92.0: chỉ xóa cache dữ liệu lịch nghỉ sau Thêm/Sửa/Xóa.
    Không xóa credentials / phân quyền / LoaiNghi / quota config để tránh gọi Google API lại vô ích.
    """
    if vpg is not None and _vpg_is_enabled():
        try:
            vpg.invalidate_many("leave_primary")
        except Exception:
            pass

    for fn_name in (
        "load_backup_sheet_data",
        "load_live_leave_registration_cached",
    ):
        try:
            fn = globals().get(fn_name)
            if fn is not None and hasattr(fn, "clear"):
                fn.clear()
        except Exception:
            pass


def _clear_dynamic_data_caches():
    """
    Cache invalidation rộng cho thay đổi hồ sơ/nhân sự/ca.
    V92.0 không xóa các cache cấu hình ít thay đổi như LoaiNghi, quota, phân quyền.
    """
    _clear_leave_data_caches()

    if vpg is not None and _vpg_is_enabled():
        try:
            vpg.invalidate_many("credentials", "tichluy")
        except Exception:
            pass

    for fn_name in (
        "load_credentials",
        "load_credentials_recent",
        "load_tichluy_tracking",
    ):
        try:
            fn = globals().get(fn_name)
            if fn is not None and hasattr(fn, "clear"):
                fn.clear()
        except Exception:
            pass


# ==========================================================
# V84 - TRẠNG THÁI AUTO UPDATE PHẠT (DÙNG CHUNG TOÀN HỆ THỐNG)
# ==========================================================
def _get_auto_penalty_config_worksheet(client=None):
    client = client or get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_DU_PHONG_ID)
    try:
        ws = ss.worksheet(AUTO_PENALTY_CONFIG_WORKSHEET)
    except Exception:
        ws = ss.add_worksheet(title=AUTO_PENALTY_CONFIG_WORKSHEET, rows=20, cols=8)
    return ws

def load_auto_penalty_config():
    """Đọc LIVE trạng thái RUNNING/PAUSED để nút Admin có hiệu lực trên mọi phiên/instance."""
    default = {
        "paused": False,
        "status": AUTO_PENALTY_RUNNING,
        "threshold_minutes": AUTO_PENALTY_MINUTES,
        "updated_date": "",
        "updated_time": "",
        "updated_by": "",
        "error": "",
    }
    try:
        client = get_gspread_client()
        ws = _get_auto_penalty_config_worksheet(client)
        if ws is None:
            default["error"] = "Chưa cấu hình Google Sheets."
            return default
        vals = _gs_call_with_backoff(ws.get, 'A1:F2')
        if not vals or not vals[0] or vals[0][:6] != AUTO_PENALTY_CONFIG_HEADERS:
            gspread_update_range(ws, 'A1:F1', [AUTO_PENALTY_CONFIG_HEADERS], value_input_option='USER_ENTERED')
        row = vals[1] if len(vals) > 1 else []
        if not row or str(row[0]).strip() != AUTO_PENALTY_CONFIG_KEY:
            now = datetime.now(VN_TZ)
            row = [
                AUTO_PENALTY_CONFIG_KEY, AUTO_PENALTY_RUNNING, AUTO_PENALTY_MINUTES,
                now.strftime('%d/%m/%Y'), now.strftime('%H:%M:%S'), 'Hệ thống'
            ]
            gspread_update_range(ws, 'A2:F2', [row], value_input_option='USER_ENTERED')
        row = list(row) + [""] * max(0, 6 - len(row))
        status = str(row[1] or AUTO_PENALTY_RUNNING).strip().upper()
        try:
            threshold = int(float(row[2] or AUTO_PENALTY_MINUTES))
        except Exception:
            threshold = AUTO_PENALTY_MINUTES
        # V84: ngưỡng nghiệp vụ cố định tối thiểu là 5 phút.
        threshold = max(AUTO_PENALTY_MINUTES, threshold)
        return {
            "paused": status == AUTO_PENALTY_PAUSED,
            "status": status,
            "threshold_minutes": threshold,
            "updated_date": str(row[3] or ""),
            "updated_time": str(row[4] or ""),
            "updated_by": str(row[5] or ""),
            "error": "",
        }
    except Exception as e:
        default["error"] = str(e)
        return default

def set_auto_penalty_paused(paused, updated_by):
    try:
        client = get_gspread_client()
        ws = _get_auto_penalty_config_worksheet(client)
        if ws is None:
            return False, "Chưa cấu hình quyền kết nối Google Sheets."
        now = datetime.now(VN_TZ)
        status = AUTO_PENALTY_PAUSED if bool(paused) else AUTO_PENALTY_RUNNING
        gspread_update_range(ws, 'A1:F1', [AUTO_PENALTY_CONFIG_HEADERS], value_input_option='USER_ENTERED')
        gspread_update_range(ws, 'A2:F2', [[
            AUTO_PENALTY_CONFIG_KEY, status, AUTO_PENALTY_MINUTES,
            now.strftime('%d/%m/%Y'), now.strftime('%H:%M:%S'), str(updated_by or 'Admin')
        ]], value_input_option='USER_ENTERED')
        state_vi = "TẠM DỪNG" if paused else "HOẠT ĐỘNG"
        return True, f"Auto Check đã chuyển sang trạng thái {state_vi}. Ngưỡng tự động: từ {AUTO_PENALTY_MINUTES} phút."
    except Exception as e:
        return False, f"Không cập nhật được trạng thái Auto Update: {e}"

def is_auto_penalty_paused():
    return bool(load_auto_penalty_config().get("paused", False))


