def _ui_device_defaults(
    size, height, px, py, radius, text="#333333", bg="#FFFFFF",
    font="Roboto", effect="Không", gap=8,
    font_weight="400", line_height=1.35, text_align="Trái",
    border_width=0, border_color="#D9D9D9", box_shadow="Không",
    hover_bg="#F2F2F2", hover_text="#222222",
    disabled_bg="#E9ECEF", disabled_text="#8A8A8A",
):
    return {
        "font_size": int(size),
        "control_height": int(height),
        "padding_x": int(px),
        "padding_y": int(py),
        "radius": int(radius),
        "gap": int(gap),
        "font_family": font,
        "font_weight": str(font_weight),
        "line_height": float(line_height),
        "text_align": text_align,
        "text_color": text,
        "bg_color": bg,
        "border_width": int(border_width),
        "border_color": border_color,
        "box_shadow": box_shadow,
        "hover_bg": hover_bg,
        "hover_text": hover_text,
        "disabled_bg": disabled_bg,
        "disabled_text": disabled_text,
        "effect": effect,
    }

