# V87.1 - TÙY CHỈNH RIÊNG BẢNG THỐNG KÊ CHI TIẾT THEO TỪNG NGÀY
# HTML class: vera-daily-summary-table
# ==========================================================
DAILY_SUMMARY_UI_KEY = "daily_summary_table_v871"
DAILY_SUMMARY_COLUMNS = [
    ("Ngày", 150, 20.0),
    ("Thứ ngày", 105, 11.0),
    ("Tổng nghỉ", 105, 11.0),
    ("✅ CÓ phép", 145, 19.0),
    ("⚠️ PHÁT SINH", 155, 19.0),
    ("❌ KHÔNG phép", 155, 20.0),
    ("💰 Tổng tiền phạt", 165, 14.0),
]
DAILY_SUMMARY_STYLE_DEFAULT = {
    "desktop": {
        "header_font": 16,
        "body_font": 16,
        "pill_font": 16,
        "padding_x": 10,
        "padding_y": 4,
        "pill_padding_y": 11,
        "pill_radius": 14,
        "row_gap": 12,
    },
    "mobile": {
        "header_font": 8,
        "body_font": 8,
        "pill_font": 8,
        "padding_x": 1,
        "padding_y": 1,
        "pill_padding_y": 4,
        "pill_radius": 7,
        "row_gap": 4,
    },
}


def _daily_summary_default_config():
    return {
        "columns": {
            label: {"desktop_px": int(px), "mobile_weight": float(weight)}
            for label, px, weight in DAILY_SUMMARY_COLUMNS
        },
        "style": json.loads(json.dumps(DAILY_SUMMARY_STYLE_DEFAULT)),
    }


def _normalize_daily_summary_ui_config(raw=None):
    base = _daily_summary_default_config()
    raw = raw if isinstance(raw, dict) else {}
    raw_cols = raw.get("columns", {}) if isinstance(raw.get("columns", {}), dict) else {}
    raw_style = raw.get("style", {}) if isinstance(raw.get("style", {}), dict) else {}

    for label, _, _ in DAILY_SUMMARY_COLUMNS:
        incoming = raw_cols.get(label, {}) if isinstance(raw_cols.get(label, {}), dict) else {}
        try:
            base["columns"][label]["desktop_px"] = max(
                55, min(500, int(float(incoming.get("desktop_px", base["columns"][label]["desktop_px"]))))
            )
        except Exception:
            pass
        try:
            base["columns"][label]["mobile_weight"] = max(
                1.0, min(100.0, float(incoming.get("mobile_weight", base["columns"][label]["mobile_weight"])))
            )
        except Exception:
            pass

    for device in ["desktop", "mobile"]:
        incoming = raw_style.get(device, {}) if isinstance(raw_style.get(device, {}), dict) else {}
        limits = {
            "header_font": (6, 30),
            "body_font": (6, 30),
            "pill_font": (6, 30),
            "padding_x": (0, 30),
            "padding_y": (0, 30),
            "pill_padding_y": (0, 30),
            "pill_radius": (0, 30),
            "row_gap": (0, 30),
        }
        for key, (lo, hi) in limits.items():
            try:
                base["style"][device][key] = max(
                    lo, min(hi, int(float(incoming.get(key, base["style"][device][key]))))
                )
            except Exception:
                pass
    return base


@st.cache_data(ttl=300, show_spinner=False)
def load_daily_summary_ui_config():
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return _daily_summary_default_config(), err
    try:
        values = _gs_call_with_backoff(ws.get_all_values)
        for row in values[1:]:
            if row and str(row[0]).strip() == DAILY_SUMMARY_UI_KEY:
                try:
                    raw = json.loads(row[1]) if len(row) > 1 and str(row[1]).strip() else {}
                except Exception:
                    raw = {}
                return _normalize_daily_summary_ui_config(raw), ""
        return _daily_summary_default_config(), ""
    except Exception as e:
        return _daily_summary_default_config(), f"Lỗi đọc cấu hình bảng thống kê ngày: {e}"


def _clear_daily_summary_ui_cache():
    try:
        load_daily_summary_ui_config.clear()
    except Exception:
        pass


def save_daily_summary_ui_config(config, username):
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return False, err or "Không mở được sheet cấu hình giao diện."
    try:
        cfg = _normalize_daily_summary_ui_config(config)
        values = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(values[1:], start=2):
            if row and str(row[0]).strip() == DAILY_SUMMARY_UI_KEY:
                row_idx = idx
                break

        now = datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")
        row_value = [
            DAILY_SUMMARY_UI_KEY,
            json.dumps(cfg, ensure_ascii=False),
            now,
            str(username),
        ]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:D{row_idx}", [row_value])
        else:
            _gs_call_with_backoff(ws.append_row, row_value, value_input_option="USER_ENTERED")
        _clear_daily_summary_ui_cache()
        return True, "Đã lưu giao diện bảng Thống kê chi tiết theo từng ngày."
    except Exception as e:
        return False, f"Lỗi lưu giao diện bảng thống kê ngày: {e}"


def _daily_summary_column_editor_df(config):
    cfg = _normalize_daily_summary_ui_config(config)
    return pd.DataFrame([
        {
            "Cột": label,
            "Desktop (px)": cfg["columns"][label]["desktop_px"],
            "Mobile (tỷ lệ)": cfg["columns"][label]["mobile_weight"],
        }
        for label, _, _ in DAILY_SUMMARY_COLUMNS
    ])


def _daily_summary_apply_column_editor(config, edited_df):
    cfg = _normalize_daily_summary_ui_config(config)
    if not isinstance(edited_df, pd.DataFrame):
        return cfg
    for _, row in edited_df.iterrows():
        label = str(row.get("Cột", "")).strip()
        if label not in cfg["columns"]:
            continue
        try:
            cfg["columns"][label]["desktop_px"] = int(float(row.get("Desktop (px)", cfg["columns"][label]["desktop_px"])))
        except Exception:
            pass
        try:
            cfg["columns"][label]["mobile_weight"] = float(row.get("Mobile (tỷ lệ)", cfg["columns"][label]["mobile_weight"]))
        except Exception:
            pass
    return _normalize_daily_summary_ui_config(cfg)


def _daily_summary_normalized_widths(config, labels, device):
    cfg = _normalize_daily_summary_ui_config(config)
    if device == "desktop":
        return [float(cfg["columns"].get(label, {}).get("desktop_px", 120)) for label in labels]

    weights = [
        max(1.0, float(cfg["columns"].get(label, {}).get("mobile_weight", 10.0)))
        for label in labels
    ]
    total = sum(weights) or 1.0
    return [(w / total) * 100.0 for w in weights]


def render_daily_summary_ui_editor():
    if st.session_state.get("current_role") != "admin":
        return
    current, err = load_daily_summary_ui_config()
    with st.expander("📅 Bảng thống kê nghỉ theo ngày · Web / Mobile", expanded=False):
        st.caption(
            "Web và Mobile luôn hiển thị song song. Độ rộng cột và style được chỉnh độc lập."
        )
        if err:
            st.warning(err)

        col_edit = st.data_editor(
            _daily_summary_column_editor_df(current),
            key="daily_summary_columns_v921",
            hide_index=True, num_rows="fixed", width="stretch", height="content",
            disabled=["Tên cột"],
            column_config={
                "Tên cột": st.column_config.TextColumn("Tên cột", disabled=True, width=190),
                "Desktop (px)": st.column_config.NumberColumn(
                    "🌐 Web (px)", min_value=55, max_value=500, step=5, format="%d", width=110
                ),
                "Mobile (tỷ lệ)": st.column_config.NumberColumn(
                    "📱 Mobile (tỷ lệ)", min_value=1.0, max_value=100.0, step=1.0, format="%.0f", width=125
                ),
            },
        )
        preview = _daily_summary_apply_column_editor(current, col_edit)

        def _edit_style(device, prefix):
            # V92.6.39:
            # Style bảng thống kê dùng 3 key font riêng:
            # header_font / body_font / pill_font.
            # Bản UI editor cũ gọi nhầm "font_size" nên gây KeyError.
            defaults = _daily_summary_default_config()["style"][device]
            out = dict(defaults)
            incoming = preview.get("style", {}).get(device, {})
            if isinstance(incoming, dict):
                out.update(incoming)

            settings = [
                ("header_font", "Cỡ chữ tiêu đề cột", 6, 30),
                ("body_font", "Cỡ chữ nội dung", 6, 30),
                ("pill_font", "Cỡ chữ ô số", 6, 30),
                ("padding_x", "Padding ngang", 0, 30),
                ("padding_y", "Padding dọc", 0, 30),
                ("pill_padding_y", "Padding dọc ô số", 0, 30),
                ("pill_radius", "Bo góc ô số", 0, 30),
                ("row_gap", "Khoảng cách hàng", 0, 30),
            ]
            for field, label, lo, hi in settings:
                fallback = int(defaults.get(field, lo))
                try:
                    current_value = int(float(out.get(field, fallback)))
                except Exception:
                    current_value = fallback
                current_value = max(lo, min(hi, current_value))
                out[field] = st.number_input(
                    label,
                    min_value=lo,
                    max_value=hi,
                    value=current_value,
                    step=1,
                    key=f"{prefix}_{field}",
                )
            return out

        web_col, mobile_col = st.columns(2)
        with web_col:
            st.markdown("#### 🌐 Web / Desktop")
            preview["style"]["desktop"] = _edit_style("desktop", "daily_summary_web_v921")
        with mobile_col:
            st.markdown("#### 📱 Mobile")
            preview["style"]["mobile"] = _edit_style("mobile", "daily_summary_mobile_v921")

        b1, b2 = st.columns(2)
        with b1:
            if st.button("💾 Lưu bảng thống kê ngày", use_container_width=True, key="save_daily_summary_ui_v921"):
                ok, msg = save_daily_summary_ui_config(preview, st.session_state.current_user)
                (st.success if ok else st.error)(msg)
                if ok:
                    rerun_current_view()
        with b2:
            if st.button("♻️ Khôi phục mặc định", use_container_width=True, key="reset_daily_summary_ui_v921"):
                ok, msg = save_daily_summary_ui_config(_daily_summary_default_config(), st.session_state.current_user)
                (st.success if ok else st.error)(msg)
                if ok:
                    rerun_current_view()



