def has_page_access(page_name):
    # V92.6.34: mọi tài khoản đã đăng nhập đều được vào trang Lịch nghỉ
    # để xem Thống kê chi tiết theo từng ngày và Chi tiết danh sách.
    # Quyền Đăng ký/Sửa/Xóa vẫn được kiểm tra riêng ở từng chức năng.
    if page_name == "📅 Đăng ký nghỉ phép":
        return True
    if page_name == "🧾 Log Book":
        return str(st.session_state.get("current_role", "") or "").strip().lower() == "admin"
    if page_name == "📘 Hướng dẫn sử dụng":
        return True
    if page_name == "🏖️ Phép năm - Làm đẹp":
        return any(
            has_feature_access(k)
            for k in {"long_leave", "long_leave_form", "long_leave_stats"}
        )
    # Trang Phân quyền vẫn chỉ Admin quản trị để tránh tự khóa hệ thống.
    if page_name == "🔐 Phân quyền chức năng":
        return st.session_state.get("current_role") == "admin"
    features = PAGE_FEATURE_GROUPS.get(page_name)
    if features:
        return any(has_feature_access(key) for key in features)
    key = PAGE_FEATURE_KEYS.get(page_name)
    return bool(key and has_feature_access(key))

