def collapse_sidebar_after_navigation_once():
    """Sau khi chọn xong một mục MENU CHỨC NĂNG, tự thu gọn sidebar một lần."""
    if not st.session_state.pop("_vera_collapse_sidebar_once", False):
        return
    components.html(r"""
    <script>
    (function(){
      try {
        const win = window.parent, doc = win.document;
        // V92.6.91: Desktop luôn giữ MENU CHỨC NĂNG mở. Auto-hide chỉ áp dụng mobile.
        if (win.matchMedia && win.matchMedia('(min-width: 769px)').matches) return;
        const clickCollapse = () => {
          const collapsedControl =
            doc.querySelector('[data-testid="collapsedControl"]')
            || doc.querySelector('[data-testid="stSidebarCollapsedControl"]');
          if (collapsedControl && collapsedControl.offsetParent !== null) return;
          const sidebar = doc.querySelector('[data-testid="stSidebar"]');
          if (!sidebar) return;
          const candidates = [
            doc.querySelector('[data-testid="stSidebarCollapseButton"] button'),
            doc.querySelector('[data-testid="stSidebarCollapseButton"]'),
            doc.querySelector('[data-testid="stSidebarHeader"] button'),
            sidebar.querySelector('button[aria-label="Close sidebar"]'),
            sidebar.querySelector('button[aria-label*="sidebar" i]'),
            sidebar.querySelector('button[kind="header"]')
          ].filter(Boolean);
          const btn = candidates.find(x => !x.disabled);
          if (btn) btn.click();
        };
        [60, 160, 320, 650, 1100].forEach(function(ms){ setTimeout(clickCollapse, ms); });
      } catch (e) {}
    })();
    </script>
    """, height=0, width=0)



def ensure_sidebar_open_on_desktop_v92691():
    """Desktop: khi mở/rerun trang phải nhìn thấy MENU CHỨC NĂNG."""
