            _sum_ps = int(pd.to_numeric(daily_stats_df.get("⚠️ PHÁT SINH", 0), errors="coerce").fillna(0).sum())
            _sum_kp = int(pd.to_numeric(daily_stats_df.get("❌ KHÔNG phép", 0), errors="coerce").fillna(0).sum())

